"use client"

import * as React from "react"
import { motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface ScrollTimelineRevealProps {
  mode?: "reveal" | "parallax"
  className?: string
  children?: React.ReactNode
  speed?: number
  intensity?: number
}

const VIEW_CSS = `@keyframes eu11-reveal { from { opacity: 0; transform: translateY(2rem); } to { opacity: 1; transform: none; } }
          @keyframes eu11-parallax { from { transform: translateY(2.5rem); } to { transform: translateY(-2.5rem); } }
          .eu11-reveal { animation: eu11-reveal linear both; animation-timeline: view(); animation-range: entry 0% cover 35%; }
          .eu11-parallax { animation: eu11-parallax linear both; animation-timeline: view(); animation-range: cover 0% cover 100%; }`

function supportsViewTimeline() {
  return CSS.supports("animation-timeline", "view()")
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

function ScrollTimelineReveal({ mode = "reveal", className, children, speed, intensity }: ScrollTimelineRevealProps) {
  const reduced = usePrefersReducedMotion()
  const supported = React.useSyncExternalStore(
    () => () => {},
    supportsViewTimeline,
    () => false,
  )
  const css = supported && !reduced
  const rate = pace(speed)
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const duration = reduced ? 0 : rate === 1 ? 0.55 : 0.55 / rate
  const revealShift = `${2 * gain}rem`
  const parallaxShift = `${2.5 * gain}rem`
  const viewCss =
    gain === 1
      ? VIEW_CSS
      : `@keyframes eu11-reveal { from { opacity: 0; transform: translateY(${revealShift}); } to { opacity: 1; transform: none; } }
          @keyframes eu11-parallax { from { transform: translateY(${parallaxShift}); } to { transform: translateY(-${parallaxShift}); } }
          .eu11-reveal { animation: eu11-reveal linear both; animation-timeline: view(); animation-range: entry 0% cover 35%; }
          .eu11-parallax { animation: eu11-parallax linear both; animation-timeline: view(); animation-range: cover 0% cover 100%; }`
  const body = children ?? (
    <div className="rounded-2xl border bg-card p-6">
      <p className="font-display text-3xl">{mode === "parallax" ? "视差" : "显现"}</p>
      <p className="mt-2 text-sm text-muted-foreground">进入视口时沿 view() 时间线运动。</p>
    </div>
  )

  return (
    <div className={cn("py-8", className)}>
      <style>{viewCss}</style>
      {css ? (
        <div className={mode === "parallax" ? "eu11-parallax" : "eu11-reveal"}>{body}</div>
      ) : (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: gain === 1 ? 28 : 28 * gain }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: mode === "reveal", amount: 0.45 }}
          transition={{ duration }}
        >
          {body}
        </motion.div>
      )}
    </div>
  )
}

function ScrollTimelineShowcase({ className }: { className?: string }) {
  return (
    <div className={cn("space-y-[28vh]", className)}>
      <ScrollTimelineReveal mode="reveal" />
      <ScrollTimelineReveal mode="parallax" />
    </div>
  )
}

export { ScrollTimelineReveal, ScrollTimelineShowcase }

"use client"

import * as React from "react"
import { motion, useScroll, useTransform } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { textStyle } from "@/lib/text-style"
import { cn } from "@/lib/utils"

export type ScrollTypographyVariant = "clip" | "blur" | "scale" | "slide"

export interface ScrollTypographyProps {
  text: string
  variant?: ScrollTypographyVariant
  className?: string
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

function ScrollTypography({
  text,
  variant = "clip",
  className,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: ScrollTypographyProps) {
  const reduced = usePrefersReducedMotion()
  const ref = React.useRef<HTMLDivElement>(null)
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start 0.9", "end 0.35"] })
  const letters = Array.from(text)

  return (
    <div
      ref={ref}
      className={cn("flex flex-wrap justify-center gap-x-1 font-display text-4xl", className)}
      style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}
    >
      {letters.map((letter, index) => (
        <Letter
          key={`${letter}-${index}`}
          progress={scrollYProgress}
          index={index}
          total={letters.length}
          variant={variant}
          reduced={reduced}
        >
          {letter === " " ? "\u00a0" : letter}
        </Letter>
      ))}
    </div>
  )
}

function Letter({
  children,
  progress,
  index,
  total,
  variant,
  reduced,
}: {
  children: string
  progress: ReturnType<typeof useScroll>["scrollYProgress"]
  index: number
  total: number
  variant: ScrollTypographyVariant
  reduced: boolean
}) {
  const start = index / total
  const end = Math.min(1, start + 0.18)
  const t = useTransform(progress, [start, end], [0, 1])
  const opacity = useTransform(t, [0, 1], reduced ? [1, 1] : [0.15, 1])
  const y = useTransform(t, [0, 1], reduced ? [0, 0] : [variant === "slide" ? 28 : 0, 0])
  const scale = useTransform(t, [0, 1], reduced ? [1, 1] : [variant === "scale" ? 1.45 : 1, 1])
  const blur = useTransform(t, [0, 1], reduced ? [0, 0] : [variant === "blur" ? 10 : 0, 0])
  const clip = useTransform(t, [0, 1], reduced ? [0, 0] : [variant === "clip" ? 100 : 0, 0])
  const filter = useTransform(blur, (value) => `blur(${value}px)`)
  const clipPath = useTransform(clip, (value) => `inset(0 ${value}% 0 0)`)

  return (
    <motion.span style={{ opacity, y, scale, filter, clipPath }} className="inline-block origin-bottom">
      {children}
    </motion.span>
  )
}

export { ScrollTypography }

"use client"

import * as React from "react"
import {
  motion,
  useAnimationFrame,
  useMotionValue,
  useScroll,
  useSpring,
  useTransform,
  useVelocity,
  type MotionValue,
} from "motion/react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

function wrap(min: number, max: number, value: number) {
  const range = max - min
  return ((((value - min) % range) + range) % range) + min
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

function scrollFactor(value: number, gain: number) {
  const sign = value < 0 ? -1 : 1
  const cap = gain === 1 ? 5 : 5 * gain
  return sign * Math.min(cap, (Math.abs(value) / 1000) * cap)
}

const VelocityContext = React.createContext<MotionValue<number> | null>(null)

function ScrollVelocity({
  children,
  className,
  intensity,
}: {
  children: React.ReactNode
  className?: string
  intensity?: number
}) {
  const reduce = usePrefersReducedMotion()
  if (reduce) {
    return <div className={cn("relative w-full", className)}>{children}</div>
  }
  return (
    <ScrollVelocityLive className={className} intensity={intensity}>
      {children}
    </ScrollVelocityLive>
  )
}

function ScrollVelocityLive({
  children,
  className,
  intensity,
}: {
  children: React.ReactNode
  className?: string
  intensity?: number
}) {
  const gainRef = React.useRef(1)
  const { scrollY } = useScroll()
  const velocity = useVelocity(scrollY)
  const smooth = useSpring(velocity, { damping: 50, stiffness: 400 })
  const factor = useTransform(smooth, (value) => scrollFactor(value, gainRef.current))

  React.useEffect(() => {
    gainRef.current = intensity === undefined || intensity === 1 ? 1 : intensity
  }, [intensity])

  return (
    <VelocityContext.Provider value={factor}>
      <div className={cn("relative w-full", className)}>{children}</div>
    </VelocityContext.Provider>
  )
}

function ScrollVelocityRow({
  children,
  className,
  baseVelocity = 5,
  direction = 1,
  speed,
  intensity,
}: {
  children: React.ReactNode
  className?: string
  baseVelocity?: number
  direction?: 1 | -1
  speed?: number
  intensity?: number
}) {
  const reduce = usePrefersReducedMotion()
  if (reduce) {
    return (
      <div className={cn("w-full overflow-hidden whitespace-nowrap", className)}>
        <div className="inline-flex items-center">{children}</div>
      </div>
    )
  }
  return (
    <ScrollVelocityRowLive
      className={className}
      baseVelocity={baseVelocity}
      direction={direction}
      speed={speed}
      intensity={intensity}
    >
      {children}
    </ScrollVelocityRowLive>
  )
}

function ScrollVelocityRowLive({
  children,
  className,
  baseVelocity = 5,
  direction = 1,
  speed,
  intensity,
}: {
  children: React.ReactNode
  className?: string
  baseVelocity?: number
  direction?: 1 | -1
  speed?: number
  intensity?: number
}) {
  const shared = React.useContext(VelocityContext)
  const gainRef = React.useRef(1)
  const rateRef = React.useRef(1)
  const { scrollY } = useScroll()
  const localVelocity = useVelocity(scrollY)
  const localSmooth = useSpring(localVelocity, { damping: 50, stiffness: 400 })
  const localFactor = useTransform(localSmooth, (value) => scrollFactor(value, gainRef.current))
  const velocityFactor = shared ?? localFactor

  const containerRef = React.useRef<HTMLDivElement>(null)
  const blockRef = React.useRef<HTMLDivElement>(null)
  const active = useAnimationActive(containerRef)
  const activeRef = React.useRef(false)
  const [copies, setCopies] = React.useState(3)
  const baseX = useMotionValue(0)
  const unitWidth = useMotionValue(0)
  const currentDirection = React.useRef(direction)

  React.useEffect(() => {
    activeRef.current = active
  }, [active])

  React.useEffect(() => {
    gainRef.current = intensity === undefined || intensity === 1 ? 1 : intensity
    rateRef.current = pace(speed)
  }, [intensity, speed])

  React.useEffect(() => {
    const container = containerRef.current
    const block = blockRef.current
    if (!container || !block) return
    const update = () => {
      const width = block.scrollWidth || 0
      unitWidth.set(width)
      const next = width > 0 ? Math.max(3, Math.ceil(container.offsetWidth / width) + 2) : 3
      setCopies((prev) => (prev === next ? prev : next))
    }
    update()
    const observer = new ResizeObserver(update)
    observer.observe(container)
    observer.observe(block)
    return () => observer.disconnect()
  }, [unitWidth])

  const x = useTransform([baseX, unitWidth], ([offset, width]) => {
    const size = Number(width) || 1
    return `${-wrap(0, size, Number(offset) || 0)}px`
  })

  useAnimationFrame((_, delta) => {
    if (!activeRef.current) return
    const vf = velocityFactor.get()
    if (Math.abs(vf) > 0.1) {
      currentDirection.current = (direction * (vf >= 0 ? 1 : -1)) as 1 | -1
    }
    const width = unitWidth.get()
    if (width <= 0) return
    const rate = rateRef.current
    const velocity = rate === 1 ? baseVelocity : baseVelocity * rate
    const move = currentDirection.current * ((width * velocity) / 100) * (1 + Math.abs(vf)) * (delta / 1000)
    baseX.set(baseX.get() + move)
  })

  return (
    <div ref={containerRef} className={cn("w-full overflow-hidden whitespace-nowrap", className)}>
      <motion.div className="inline-flex will-change-transform" style={{ x }}>
        {Array.from({ length: copies }, (_, index) => (
          <div
            key={index}
            ref={index === 0 ? blockRef : undefined}
            aria-hidden={index !== 0}
            className="inline-flex shrink-0 items-center"
          >
            {children}
          </div>
        ))}
      </motion.div>
    </div>
  )
}

export { ScrollVelocity, ScrollVelocityRow }

