"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/scrubber/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"

import { cn } from "@/lib/utils"
import { motion } from "motion/react";
import { useCallback, useRef, useState, useSyncExternalStore } from "react";

export interface ScrubberProps {
  /** Additional CSS classes */
  className?: string;
  /** Number of decimal places to display */
  decimals?: number;
  /** Default value for uncontrolled usage */
  defaultValue?: number;
  /** Label displayed on the left side of the track */
  label?: string;
  /** Maximum value */
  max?: number;
  /** Minimum value */
  min?: number;
  /** Called when value changes during interaction */
  onValueChange?: (value: number) => void;
  /** Step increment */
  step?: number;
  /** Number of tick marks (0 to hide) */
  ticks?: number;
  /** Controlled value */
  value?: number;
}

const clamp = (val: number, min: number, max: number) =>
  Math.min(Math.max(val, min), max);

const roundToStep = (val: number, step: number, min: number) =>
  Math.round((val - min) / step) * step + min;

const Scrubber = ({
  label = "Value",
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = 0,
  max = 1,
  step = 0.01,
  decimals = 2,
  ticks = 9,
  className,
}: ScrubberProps) => {
  const shouldReduceMotion = usePrefersReducedMotion();
  const trackRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [isDragging, setIsDragging] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const isHoverDevice = useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
      mq.addEventListener("change", onChange);
      return () => mq.removeEventListener("change", onChange);
    },
    () => window.matchMedia("(hover: hover) and (pointer: fine)").matches,
    () => false,
  );

  const isControlled = controlledValue !== undefined;
  const value = isControlled ? controlledValue : internalValue;
  const range = max - min;
  const percentage = range > 0 ? ((value - min) / range) * 100 : 0;
  const isActive = isDragging || (isHoverDevice && isHovering);

  const setValue = useCallback(
    (newValue: number) => {
      const clamped = clamp(roundToStep(newValue, step, min), min, max);
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onValueChange?.(clamped);
    },
    [step, min, max, isControlled, onValueChange]
  );

  const getValueFromPointer = useCallback(
    (clientX: number) => {
      const track = trackRef.current;
      if (!track) {
        return value;
      }
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      return min + ratio * range;
    },
    [min, range, value]
  );

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      trackRef.current?.setPointerCapture(e.pointerId);
      setIsDragging(true);
      setValue(getValueFromPointer(e.clientX));
    },
    [getValueFromPointer, setValue]
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging) {
        return;
      }
      setValue(getValueFromPointer(e.clientX));
    },
    [isDragging, getValueFromPointer, setValue]
  );

  const handlePointerUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      let next: number | undefined;
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          next = value + step;
          break;
        case "ArrowLeft":
        case "ArrowDown":
          next = value - step;
          break;
        case "Home":
          next = min;
          break;
        case "End":
          next = max;
          break;
        default:
          return;
      }
      e.preventDefault();
      setValue(next);
    },
    [value, step, min, max, setValue]
  );

  const springConfig = shouldReduceMotion
    ? { duration: 0 }
    : { bounce: 0.1, duration: 0.25, type: "spring" as const };

  return (
    <div className={cn("relative w-full select-none", className)} data-reduced={shouldReduceMotion ? "true" : "false"} data-slot="scrubber">
      <div
        aria-label={label}
        aria-valuemax={max}
        aria-valuemin={min}
        aria-valuenow={Number(value.toFixed(decimals))}
        className="relative cursor-pointer overflow-hidden bg-muted outline-offset-2"
        onKeyDown={handleKeyDown}
        onMouseEnter={() => setIsHovering(true)}
        onMouseLeave={() => setIsHovering(false)}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={trackRef}
        role="slider"
        style={{
          borderRadius: 8,
          height: 36,
          touchAction: "none",
        }}
        tabIndex={0}
      >
        {/* Fill indicator */}
        <div
          className="pointer-events-none absolute inset-y-0 left-0 bg-foreground/14"
          style={{
            borderRadius: 8,
            transition: isDragging
              ? "none"
              : "width 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            width: `${percentage}%`,
          }}
        />

        {/* Tick marks */}
        {ticks > 0 && (
          <div className="pointer-events-none absolute inset-0">
            {Array.from({ length: ticks }, (_, i) => {
              const pos = ((i + 1) / (ticks + 1)) * 100;
              return (
                <div
                  className="absolute top-1/2 bg-foreground/25"
                  key={pos}
                  style={{
                    borderRadius: 999,
                    height: 6,
                    left: `${pos}%`,
                    transform: "translateX(-50%) translateY(-50%)",
                    width: 1,
                  }}
                />
              );
            })}
          </div>
        )}

        {/* Scrub bar (capsule thumb) */}
        <div
          className="pointer-events-none absolute"
          style={{
            left: `${percentage}%`,
            marginLeft: -5,
            top: "50%",
            transform: "translateX(-50%) translateY(-50%)",
            transition: isDragging
              ? "none"
              : "left 150ms cubic-bezier(0.23, 1, 0.32, 1)",
            zIndex: 3,
          }}
        >
          <motion.div
            animate={{
              opacity: isActive ? 0.8 : 0.15,
              scaleX: isActive ? 1 : 0.7,
              scaleY: isActive ? 1 : 0.7,
            }}
            className="bg-foreground/90"
            style={{
              borderRadius: 999,
              height: 22,
              width: 4,
            }}
            transition={springConfig}
          />
        </div>

        {/* Label */}
        <div
          className="pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 whitespace-nowrap text-foreground"
          style={{
            fontSize: 13,
            fontWeight: 500,
            zIndex: 4,
          }}
        >
          {label}
        </div>

        {/* Value display */}
        <div
          className="pointer-events-none absolute top-1/2 right-2.5 -translate-y-1/2 text-foreground"
          style={{
            fontFamily: "ui-monospace, monospace",
            fontSize: 13,
            fontVariantNumeric: "tabular-nums",
            fontWeight: 500,
            zIndex: 4,
          }}
        >
          {value.toFixed(decimals)}
        </div>
      </div>
    </div>
  );
};

export { Scrubber }

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/sdf-blob-transition/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { useAnimationActive } from "@/hooks/use-animation-active"
import { Camera, Geometry, Mesh, Program, Renderer, Transform } from "ogl"

import { cn } from "@/lib/utils"
import { type ReactNode, useEffect, useRef, useState } from "react";

export type SdfBlobVariant = "circle" | "warped" | "merge" | "radial" | "final";

export interface SdfBlobTransitionProps {
  children: ReactNode;
  className?: string;
  duration?: number;
  onRest?: () => void;
  transitionKey: string | number;
  variant?: SdfBlobVariant;
}

const DEFAULT_DURATION_MS = 1120;
const MIDPOINT = 0.5;
const MAX_DPR = 2;
const VERTEX_SHADER =
  "attribute vec2 a; void main(){ gl_Position = vec4(a, 0.0, 1.0); }";
const FRAGMENT_SHADER = `
precision mediump float;
uniform vec2 uRes;
uniform float uTime;
uniform float uProgress;
uniform float uAlpha;
uniform float uVariant;
#define PI 3.14159265359

float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float noise(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float circleSdf(vec2 p, vec2 c, float r){ return length(p - c) - r; }
float smin(float a, float b, float k){
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

void main(){
  vec2 uv = gl_FragCoord.xy / uRes;
  vec2 aspect = vec2(uRes.x / uRes.y, 1.0);
  vec2 p = (uv - 0.5) * aspect;
  float progress = smoothstep(0.0, 1.0, uProgress);
  float grow = smoothstep(0.0, 0.86, progress);
  float exitFade = smoothstep(1.0, 0.72, progress);

  float wobble = noise(uv * 7.0 + uTime * 0.18) * 0.035;
  float ringNoise = noise(vec2(atan(p.y, p.x) * 2.0, uTime * 0.18)) * 0.075;
  float dCircle = circleSdf(p, vec2(0.0), 0.04 + grow * 0.64);
  float dWarped = circleSdf(p, vec2(0.0), 0.04 + grow * 0.62 + ringNoise * smoothstep(0.08, 0.96, progress));

  float m0 = circleSdf(p, vec2(-0.26, -0.08), 0.06 + grow * 0.42 + wobble);
  float m1 = circleSdf(p, vec2(0.24, 0.12), 0.06 + grow * 0.40 - wobble * 0.5);
  float dMerge = smin(m0, m1, 0.18);

  float angle = atan(p.y, p.x);
  float sector3 = 2.0 * PI / 3.0;
  float sector5 = 2.0 * PI / 5.0;
  float a3 = floor((angle + PI) / sector3 + 0.5) * sector3 - PI;
  float a5 = floor((angle + PI) / sector5 + 0.5) * sector5 - PI;
  float r0 = 0.17 + grow * 0.24;
  float r1 = 0.30 + grow * 0.18;
  float dR0 = circleSdf(p, vec2(cos(a3), sin(a3)) * r0, 0.04 + grow * 0.22 + wobble * 0.4);
  float dR1 = circleSdf(p, vec2(cos(a5), sin(a5)) * r1, 0.035 + grow * 0.18);
  float dRadial = smin(dR0, dR1, 0.14);

  float f0 = circleSdf(p, vec2(-0.28, -0.10), 0.08 + grow * 0.46 + wobble);
  float f1 = circleSdf(p, vec2(0.00, 0.16), 0.06 + grow * 0.42 - wobble * 0.5);
  float f2 = circleSdf(p, vec2(0.30, -0.06), 0.05 + grow * 0.40 + wobble * 0.6);
  float f3 = circleSdf(p, vec2(-0.02, -0.30), 0.04 + grow * 0.34);
  float dFinal = smin(smin(f0, f1, 0.18), smin(f2, f3, 0.16), 0.20);
  dFinal = smin(dFinal, dRadial, 0.16);

  float d = dFinal;
  if (uVariant < 0.5) {
    d = dCircle;
  } else if (uVariant < 1.5) {
    d = dWarped;
  } else if (uVariant < 2.5) {
    d = dMerge;
  } else if (uVariant < 3.5) {
    d = dRadial;
  }

  float edge = exp(-d * d * 160.0) * exitFade;
  float fill = smoothstep(0.08, -0.10, d) * smoothstep(0.0, 0.18, progress) * exitFade;
  float cell = hash(floor((uv + noise(uv * 11.0) * 0.01) * uRes / 7.0) + floor(uTime * 10.0));
  float flecks = step(0.78, cell) * edge * 0.22 * smoothstep(1.5, 4.0, uVariant);

  vec3 rose = vec3(1.0, 0.23, 0.58);
  vec3 apricot = vec3(1.0, 0.70, 0.38);
  vec3 mint = vec3(0.42, 0.94, 0.78);
  vec3 color = mix(rose, apricot, smoothstep(-0.35, 0.35, p.x + noise(uv * 5.0) * 0.18));
  color = mix(color, mint, smoothstep(0.12, 0.7, p.y + grow * 0.16));

  float alpha = (fill * 0.24 + edge * 0.72 + flecks) * uAlpha;
  gl_FragColor = vec4(color * alpha + vec3(1.0) * edge * 0.18 * uAlpha, clamp(alpha, 0.0, 0.9));
}
`;
const STRIP = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

interface Playback {
  cancel: () => void;
}
interface Controller {
  destroy: () => void;
  setAlpha: (alpha: number) => void;
  setProgress: (progress: number) => void;
  setRunning: (running: boolean) => void;
  setVariant: (variant: SdfBlobVariant) => void;
}

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const easeOutQuart = (value: number) => 1 - (1 - value) ** 4;
const easeInOutCubic = (value: number) =>
  value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2;

const variantToUniform = (variant: SdfBlobVariant) => {
  switch (variant) {
    case "circle":
      return 0;
    case "warped":
      return 1;
    case "merge":
      return 2;
    case "radial":
      return 3;
    default:
      return 4;
  }
};

const resizeSurface = (canvas: HTMLCanvasElement, renderer: Renderer) => {
  const rect = (canvas.parentElement ?? canvas).getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
  renderer.dpr = dpr;
  renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1));
};

const createController = (
  canvas: HTMLCanvasElement,
  initialVariant: SdfBlobVariant
): Controller | null => {
  const support = document.createElement("canvas").getContext("webgl");
  if (!support) {
    return null;
  }
  let renderer: Renderer;
  try {
    renderer = new Renderer({
      canvas,
      webgl: 1,
      alpha: true,
      antialias: false,
      depth: false,
      premultipliedAlpha: true,
      dpr: 1,
      autoClear: true,
    });
  } catch {
    return null;
  }
  const gl = renderer.gl;
  if (!gl) {
    return null;
  }
  const uniforms = {
    uRes: { value: [1, 1] },
    uTime: { value: 0 },
    uProgress: { value: 0 },
    uAlpha: { value: 0 },
    uVariant: { value: variantToUniform(initialVariant) },
  };
  const program = new Program(gl, {
    vertex: VERTEX_SHADER,
    fragment: FRAGMENT_SHADER,
    uniforms,
    transparent: true,
    depthTest: false,
    depthWrite: false,
  });
  if (!gl.getProgramParameter(program.program, gl.LINK_STATUS)) {
    gl.getExtension("WEBGL_lose_context")?.loseContext();
    return null;
  }
  program.setBlendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
  const geometry = new Geometry(gl, {
    a: { size: 2, data: STRIP },
    index: { data: new Uint16Array([0, 1, 2, 2, 1, 3]) },
  });
  const mesh = new Mesh(gl, { geometry, program, frustumCulled: false });
  const scene = new Transform();
  mesh.setParent(scene);
  const camera = new Camera(gl);
  camera.position.z = 1;

  const startedAt = performance.now();
  let progress = 0;
  let alpha = 0;
  let variant = initialVariant;
  let frame = 0;
  let running = false;
  let destroyed = false;

  const draw = () => {
    if (destroyed) {
      return;
    }
    resizeSurface(canvas, renderer);
    gl.clearColor(0, 0, 0, 0);
    uniforms.uRes.value = [canvas.width, canvas.height];
    uniforms.uTime.value = (performance.now() - startedAt) / 1000;
    uniforms.uProgress.value = progress;
    uniforms.uAlpha.value = alpha;
    uniforms.uVariant.value = variantToUniform(variant);
    renderer.render({ scene, camera, frustumCull: false });
  };

  const tick = () => {
    if (destroyed || !running) {
      return;
    }
    draw();
    frame = requestAnimationFrame(tick);
  };

  resizeSurface(canvas, renderer);

  return {
    destroy: () => {
      destroyed = true;
      running = false;
      cancelAnimationFrame(frame);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
    },
    setAlpha: (nextAlpha: number) => {
      alpha = clamp01(nextAlpha);
    },
    setProgress: (nextProgress: number) => {
      progress = clamp01(nextProgress);
    },
    setRunning: (next: boolean) => {
      if (destroyed || running === next) {
        return;
      }
      running = next;
      if (next) {
        frame = requestAnimationFrame(tick);
      } else {
        cancelAnimationFrame(frame);
      }
    },
    setVariant: (nextVariant: SdfBlobVariant) => {
      variant = nextVariant;
    },
  };
};


const play = (
  controller: Controller,
  duration: number,
  onMidpoint: () => void,
  onComplete: () => void
): Playback => {
  let frame = 0;
  let cancelled = false;
  let didSwap = false;
  const startedAt = performance.now();
  controller.setAlpha(1);

  const advance = () => {
    if (cancelled) {
      return;
    }
    const raw = clamp01((performance.now() - startedAt) / duration);
    const progress = easeOutQuart(raw);
    controller.setProgress(progress);
    if (!(didSwap || progress < MIDPOINT)) {
      didSwap = true;
      onMidpoint();
    }
    if (raw < 1) {
      frame = requestAnimationFrame(advance);
      return;
    }
    if (!didSwap) {
      onMidpoint();
    }
    const fadeStartedAt = performance.now();
    const fade = () => {
      if (cancelled) {
        return;
      }
      const fadeRaw = clamp01((performance.now() - fadeStartedAt) / 90);
      controller.setAlpha(1 - easeInOutCubic(fadeRaw));
      if (fadeRaw < 1) {
        frame = requestAnimationFrame(fade);
        return;
      }
      controller.setAlpha(0);
      controller.setProgress(0);
      onComplete();
    };
    frame = requestAnimationFrame(fade);
  };
  frame = requestAnimationFrame(advance);

  return {
    cancel: () => {
      cancelled = true;
      cancelAnimationFrame(frame);
    },
  };
};

const SdfBlobTransition = ({
  children,
  className,
  duration = DEFAULT_DURATION_MS,
  onRest,
  transitionKey,
  variant = "final",
}: SdfBlobTransitionProps) => {
  const shouldReduceMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<Controller | null>(null);
  const playbackRef = useRef<Playback | null>(null);
  const previousKey = useRef(transitionKey);
  const [renderedChildren, setRenderedChildren] = useState(children);
  const [isActive, setIsActive] = useState(false);
  const runRef = useRef(false);

  useEffect(() => {
    runRef.current = motionOn && !shouldReduceMotion;
    controllerRef.current?.setRunning(runRef.current);
  }, [motionOn, shouldReduceMotion]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const controller = createController(canvas, variant);
    controllerRef.current = controller;
    controller?.setRunning(runRef.current);
    return () => {
      playbackRef.current?.cancel();
      controller?.destroy();
      controllerRef.current = null;
    };
  }, [variant]);


  useEffect(() => {
    if (previousKey.current === transitionKey) {
      queueMicrotask(() => setRenderedChildren(children));
      return;
    }
    previousKey.current = transitionKey;
    playbackRef.current?.cancel();

    if (shouldReduceMotion) {
      queueMicrotask(() => {
        setRenderedChildren(children);
        setIsActive(false);
        onRest?.();
      });
      return;
    }

    const controller = controllerRef.current;
    if (!controller) {
      queueMicrotask(() => {
        setRenderedChildren(children);
        onRest?.();
      });
      return;
    }
    controller.setVariant(variant);
    queueMicrotask(() => setIsActive(true));
    playbackRef.current = play(
      controller,
      duration,
      () => setRenderedChildren(children),
      () => {
        setIsActive(false);
        playbackRef.current = null;
        onRest?.();
      }
    );
  }, [children, duration, onRest, shouldReduceMotion, transitionKey, variant]);

  return (
    <div
      className={cn(
        "relative isolate overflow-hidden rounded-2xl bg-background text-foreground",
        className
      )}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="sdf-blob-transition"
      data-transitioning={isActive ? "true" : "false"}
      ref={hostRef}
    >
      <div className="relative z-0">{renderedChildren}</div>
      <canvas
        className={cn(
          "pointer-events-none absolute inset-0 z-10 h-full w-full transition-opacity duration-75",
          isActive && !shouldReduceMotion ? "opacity-100" : "opacity-0"
        )}
        ref={canvasRef}
      />
    </div>
  );
};

export { SdfBlobTransition }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface SeaWavesBackgroundProps {
  className?: string
  intensity?: number
  speed?: number
  colors?: readonly string[]
  scale?: number
}

const DEFAULT_COLORS = ["#05142e", "#0d597a", "#dbe8f2"] as const

type Rgb = [number, number, number]

function useSynced(prop: number | undefined, fallback: number) {
  const [draft, setDraft] = React.useState<{ prop: number | undefined; value: number } | null>(null)
  const value = draft && Object.is(draft.prop, prop) ? draft.value : (prop ?? fallback)
  return [value, (next: number) => setDraft({ prop, value: next })] as const
}

function hexToRgb(hex: string, fallback: Rgb): Rgb {
  const text = hex.trim().replace(/^#/, "")
  const digits = text.length === 3 ? [...text].map((char) => `${char}${char}`).join("") : text
  if (!/^[0-9a-fA-F]{6}$/.test(digits)) return fallback
  const value = Number.parseInt(digits, 16)
  return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
}

const VERT = `
attribute vec2 uv;
attribute vec3 position;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 1.0);
}
`

const FRAG = `
precision highp float;
uniform float u_time;
uniform float u_storm;
uniform float u_rate;
uniform float u_scale;
uniform vec3 u_deep;
uniform vec3 u_shore;
uniform vec3 u_sky;
varying vec2 vUv;

float wave(float x, float freq, float speed, float phase) {
  return sin(x * freq * u_scale + u_time * speed * u_rate + phase);
}

void main() {
  float amp = mix(0.025, 0.09, u_storm);
  float speed = mix(0.7, 2.4, u_storm);
  float y = 0.42;
  y += wave(vUv.x, 7.0, speed, 0.0) * amp;
  y += wave(vUv.x, 13.0, speed * 1.3, 1.7) * amp * 0.55;
  y += wave(vUv.x, 3.0, speed * 0.6, 0.4) * amp * 1.3;
  float crest = smoothstep(0.03, 0.0, abs(vUv.y - y));
  float below = step(vUv.y, y);
  vec3 skyLow = mix(u_shore, u_sky, vec3(0.61728395, 0.66071429, 0.80851064));
  vec3 deep = mix(u_deep, u_shore, vUv.y);
  vec3 sky = mix(skyLow, u_sky, vUv.y);
  vec3 color = mix(sky, deep, below);
  color = mix(color, vec3(0.95, 0.98, 1.0), crest * mix(0.65, 1.0, u_storm));
  gl_FragColor = vec4(color, 1.0);
}
`

function SeaFallback({ storm }: { storm: number }) {
  return (
    <div
      className="absolute inset-0"
      style={{
        background:
          storm > 0.5
            ? "linear-gradient(#94a3b8, #0f172a 45%, #082f49)"
            : "linear-gradient(#dbeafe, #38bdf8 40%, #0c4a6e)",
      }}
    />
  )
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function SeaWavesBackground({
  className,
  intensity,
  speed = 1,
  colors = DEFAULT_COLORS,
  scale = 1,
}: SeaWavesBackgroundProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const stormRef = React.useRef(intensity ?? 0.15)
  const speedRef = React.useRef(playbackRate(speed))
  const colorsRef = React.useRef(colors)
  const scaleRef = React.useRef(scale)
  const active = useAnimationActive(hostRef)
  const [storm, setStorm] = useSynced(intensity, 0.15)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback

  React.useEffect(() => {
    stormRef.current = storm
    speedRef.current = playbackRate(speed)
    colorsRef.current = colors
    scaleRef.current = scale
  }, [storm, speed, colors, scale])

  React.useEffect(() => {
    if (!showCanvas || !active) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl)
      camera.position.z = 1
      const scene = new ogl.Transform()
      const geometry = new ogl.Plane(gl, { width: 2, height: 2 })
      const uniforms = {
        u_time: { value: 0 },
        u_storm: { value: stormRef.current },
        u_rate: { value: speedRef.current },
        u_scale: { value: scaleRef.current },
        u_deep: { value: hexToRgb(colorsRef.current[0] ?? DEFAULT_COLORS[0], [0.02, 0.08, 0.18]) },
        u_shore: { value: hexToRgb(colorsRef.current[1] ?? DEFAULT_COLORS[1], [0.05, 0.35, 0.48]) },
        u_sky: { value: hexToRgb(colorsRef.current[2] ?? DEFAULT_COLORS[2], [0.86, 0.91, 0.95]) },
      }
      const program = new ogl.Program(gl, { vertex: VERT, fragment: FRAG, uniforms })
      const mesh = new ogl.Mesh(gl, { geometry, program })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const started = performance.now()
      const tick = () => {
        uniforms.u_time.value = (performance.now() - started) / 1000
        uniforms.u_storm.value = stormRef.current
        uniforms.u_rate.value = speedRef.current
        uniforms.u_scale.value = scaleRef.current
        uniforms.u_deep.value = hexToRgb(colorsRef.current[0] ?? DEFAULT_COLORS[0], [0.02, 0.08, 0.18])
        uniforms.u_shore.value = hexToRgb(colorsRef.current[1] ?? DEFAULT_COLORS[1], [0.05, 0.35, 0.48])
        uniforms.u_sky.value = hexToRgb(colorsRef.current[2] ?? DEFAULT_COLORS[2], [0.86, 0.91, 0.95])
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [active, showCanvas])

  const label = storm < 0.35 ? "平静" : storm < 0.7 ? "有浪" : "风暴"

  return (
    <div data-slot="sea-waves-background" className={cn("w-full space-y-3", className)}>
      <label className="flex items-center gap-3 text-sm">
        海况
        <input
          type="range"
          min={0}
          max={1}
          step={0.01}
          value={storm}
          aria-valuetext={label}
          className="w-40"
          onChange={(event) => setStorm(Number(event.target.value))}
        />
        <span>{label}</span>
      </label>
      <div ref={hostRef} className="relative h-72 overflow-hidden rounded-xl border">
        {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : <SeaFallback storm={storm} />}
      </div>
    </div>
  )
}

export { SeaWavesBackground }

