  )

const presetSpeed: Record<ShaderPack2Variant, number> = {
  "liquid-metal": 1,
  "god-rays": 0.75,
  water: 1,
  "smoke-ring": 0.5,
  "pulsing-border": 1,
  voronoi: 0.5,
  swirl: 0.32,
