function installMatchMedia(reduce = false) {
  window.matchMedia = (query: string) =>
    ({
      matches: reduce && query.includes("prefers-reduced-motion"),
      media: query,
      onchange: null,
      addEventListener: () => {},
      removeEventListener: () => {},
      dispatchEvent: () => false,
      addListener: () => {},
      removeListener: () => {},
    }) as unknown as MediaQueryList
}

class SilentObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
  takeRecords() {
    return []
  }
}

function markup(node: Element) {
  return node.outerHTML.replace(/ id="[^"]*"/g, "").replace(/url\(#[^)]*\)/g, "url(#id)")
}

function Beam({
  pathWidth,
  duration,
  delay,
}: {
  pathWidth?: number
  duration?: number
  delay?: number
}) {
  const container = React.useRef<HTMLDivElement>(null)
  const from = React.useRef<HTMLDivElement>(null)
  const to = React.useRef<HTMLDivElement>(null)
  return (
    <div ref={container}>
      <span ref={from}>A</span>
      <span ref={to}>B</span>
      <AnimatedBeam
        containerRef={container}
        fromRef={from}
        toRef={to}
        pathWidth={pathWidth}
        duration={duration}
        delay={delay}
      />
    </div>
  )
}

