import * as React from "react"

import { Lightbox } from "@/components/ui/lightbox"
import { ReactionBar, type ReactionItem } from "@/components/ui/reaction-bar"
import { cn } from "@/lib/utils"

export interface SocialPost {
  id: string
  author: string
  time: string
  body: string
  images: string[]
  reactions: ReactionItem[]
}

export interface SocialPostFeedProps {
  className?: string
  posts?: SocialPost[]
}

const FROZEN_NOW = Date.parse("2026-10-20T18:00:00Z")

function swatch(color: string) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600"><rect width="100%" height="100%" fill="${color}"/></svg>`
  return `data:image/svg+xml,${encodeURIComponent(svg)}`
}

const STARTER: SocialPost[] = [
  {
    id: "p1",
    author: "林夏",
    time: "2 小时前",
    body: "今天把工作室的北窗擦干净了。下午的光会在地板上停很久，久到可以把它当成一种天气。",
    images: [swatch("#fb7185"), swatch("#38bdf8")],
    reactions: [
      { emoji: "👍", count: 12 },
      { emoji: "❤️", count: 4 },
      { emoji: "🎉", count: 1 },
    ],
  },
  {
    id: "p2",
    author: "周宁",
    time: "昨天",
    body: "四张样张都留下来了。第一张是门口，第二张是楼梯，第三张是桌上的杯子，第四张是还没写完的句子。展开之后才能看见后半句：我们决定把周五留空。",
    images: [swatch("#f59e0b"), swatch("#34d399"), swatch("#818cf8"), swatch("#f472b6")],
    reactions: [
      { emoji: "👍", count: 3 },
      { emoji: "❤️", count: 8 },
      { emoji: "🎉", count: 2 },
    ],
  },
]

function ImageGrid({ images, onOpen }: { images: string[]; onOpen: (index: number) => void }) {
  const count = Math.min(images.length, 4)
  if (count === 0) return null
  return (
    <div className={cn("mt-3 grid gap-1", count === 1 ? "grid-cols-1" : "grid-cols-2")}>
      {images.slice(0, 4).map((src, index) => (
        <button
          key={`${src}-${index}`}
          type="button"
          className={cn("overflow-hidden rounded-md", count === 3 && index === 0 && "row-span-2")}
          onClick={() => onOpen(index)}
        >
          <span aria-hidden className="block aspect-4/3 bg-cover" style={{ backgroundImage: `url("${src}")` }} />
        </button>
      ))}
    </div>
  )
}

function SocialPostFeed({ className, posts: postsProp }: SocialPostFeedProps) {
  const [posts, setPosts] = React.useState(postsProp ?? STARTER)
  const [draft, setDraft] = React.useState("")
  const [expanded, setExpanded] = React.useState<Record<string, boolean>>({})
  const [lightbox, setLightbox] = React.useState<{ id: string; index: number } | null>(null)
  const openPost = posts.find((post) => post.id === lightbox?.id)

  const publish = () => {
    const body = draft.trim()
    if (!body) return
    setPosts((current) => [
      {
        id: `local-${current.length + 1}`,
        author: "你",
        time: "刚刚",
        body,
        images: [],
        reactions: [
          { emoji: "👍", count: 0 },
          { emoji: "❤️", count: 0 },
          { emoji: "🎉", count: 0 },
        ],
      },
      ...current,
    ])
    setDraft("")
  }

  const toggle = (id: string, emoji: string) => {
    setPosts((current) =>
      current.map((post) =>
        post.id === id
          ? {
              ...post,
              reactions: post.reactions.map((item) =>
                item.emoji === emoji
                  ? { ...item, active: !item.active, count: item.count + (item.active ? -1 : 1) }
                  : item,
              ),
            }
          : post,
      ),
    )
  }

  return (
    <div data-slot="social-post-feed" className={cn("w-full max-w-xl space-y-4", className)}>
      <form
        className="space-y-2 rounded-xl border p-3"
        onSubmit={(event) => {
          event.preventDefault()
          publish()
        }}
      >
        <label className="block text-sm">
          写一条帖子
          <textarea
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            className="mt-1 min-h-20 w-full rounded-md border bg-background px-2 py-1.5"
          />
        </label>
        <button type="submit" className="rounded-md bg-primary px-3 py-1.5 text-sm text-primary-foreground">
          发布
        </button>
      </form>
      <ul className="space-y-3">
        {posts.map((post) => {
          const long = post.body.length > 48
          const shown = expanded[post.id] || !long ? post.body : `${post.body.slice(0, 48)}…`
          return (
            <li key={post.id} className="rounded-xl border p-3">
              <div className="flex items-baseline justify-between gap-2">
                <span className="font-medium">{post.author}</span>
                <time dateTime={new Date(FROZEN_NOW).toISOString()} className="text-xs text-muted-foreground">
                  {post.time}
                </time>
              </div>
              <p className="mt-2 text-sm">{shown}</p>
              {long ? (
                <button type="button" className="mt-1 text-xs text-primary" onClick={() => setExpanded((current) => ({ ...current, [post.id]: !current[post.id] }))}>
                  {expanded[post.id] ? "收起" : "展开更多"}
                </button>
              ) : null}
              <ImageGrid images={post.images} onOpen={(index) => setLightbox({ id: post.id, index })} />
              <ReactionBar className="mt-3" items={post.reactions} onToggle={(emoji) => toggle(post.id, emoji)} />
            </li>
          )
        })}
      </ul>
      <Lightbox
        open={Boolean(openPost)}
        index={lightbox?.index ?? 0}
        slides={(openPost?.images ?? []).map((src) => ({ src }))}
        onClose={() => setLightbox(null)}
      />
    </div>
  )
}

export { SocialPostFeed }

