const ICON_SIZE = 36;
const ICON_GAP = 16;

const defaultPlatforms: Platform[] = [
  {
    domain: "x.com",
    icon: <XIcon className="h-5 w-5" />,
    name: "X",
    url: "https://x.com/educalvolpz",
