export interface SocialSelectorProps {
  className?: string;
  handle?: string;
  onChange?: (platform: Platform) => void;
  platforms?: Platform[];
  selectedPlatform?: Platform;
}

export function SocialSelector({
  platforms = defaultPlatforms,
  handle = "educalvolpz",
  selectedPlatform: controlledSelected,
  onChange,
  className = "",
}: SocialSelectorProps) {
  const fallbackPlatform = platforms[0] ?? defaultPlatforms[0];
  const [internalSelected, setInternalSelected] = useState<Platform | undefined>(
    fallbackPlatform
  );
  const prefersReducedMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const shouldReduceMotion = prefersReducedMotion || !motionOn;
  const selectedPlatform = controlledSelected ?? internalSelected ?? fallbackPlatform;
  if (!selectedPlatform) {
    return null;
  }

  return (
    <div
      className={`mx-auto my-4 w-full max-w-2xl text-center ${className}`}
      data-reduced={prefersReducedMotion ? "true" : "false"}
      data-slot="social-selector"
      ref={hostRef}
    >
      <div className="space-y-6">
        <div className="flex items-center justify-center">
          <div className="relative flex w-fit items-center justify-center gap-4">
            {platforms.map((platform) => (
              <button
                aria-label={`Select ${platform.name} platform`}
                className={`relative z-10 cursor-pointer rounded-full p-2 transition-colors ${
                  selectedPlatform.name === platform.name
                    ? "fill-foreground"
                    : "fill-primary-foreground hover:bg-primary"
                }`}
                key={platform.name}
                onClick={() => {
                  if (onChange) {
                    onChange(platform);
                  } else {
                    setInternalSelected(platform);
                  }
                }}
                type="button"
              >
                {platform.icon}
                <span className="sr-only">{platform.name}</span>
              </button>
            ))}
            <motion.div
              animate={
                shouldReduceMotion
                  ? {}
                  : {
                      x:
                        platforms.findIndex(
                          (p) => p.name === selectedPlatform.name
                        ) *
                        (ICON_SIZE + ICON_GAP),
                    }
              }
              className="absolute inset-0 z-0 h-9 w-9 rounded-full border bg-background"
              initial={false}
              layoutId={shouldReduceMotion ? undefined : "background"}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      damping: 30,
                      duration: 0.25,
                      stiffness: 500,
                      type: "spring" as const,
                    }
              }
            />
          </div>
        </div>
        <p className="text-md text-primary-foreground">
          Updates on{" "}
          <span className="font-medium text-foreground">
            <motion.a
              animate={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { filter: "blur(0px)", opacity: 1, y: 0 }
              }
              exit={
                shouldReduceMotion
                  ? { opacity: 0, transition: { duration: 0 } }
                  : { filter: "blur(5px)", opacity: 0, y: -10 }
              }
              href={selectedPlatform.url}
              initial={
                shouldReduceMotion
                  ? { opacity: 1 }
                  : { filter: "blur(5px)", opacity: 0, y: 10 }
              }
              key={selectedPlatform.domain}
              rel="noopener noreferrer"
              target="_blank"
              transition={
                shouldReduceMotion ? { duration: 0 } : { duration: 0.25 }
              }
            >
              {selectedPlatform.domain}
            </motion.a>
          </span>
          <br />
          <a
            className="font-medium text-foreground"
            href={selectedPlatform.url}
            rel="noopener noreferrer"
            target="_blank"
          >
            @{handle}
          </a>
        </p>
      </div>
    </div>
  );
}

