import * as React from "react"
import { motion, type Variants } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface SplitTextProps {
  text: string
  /** 入场延迟，单位秒。保持原含义。 */
  delay?: number
  by?: "char" | "word"
  className?: string
  /** 入场结束后再播一次。不传则只播一次。 */
  loop?: boolean
  /** 精细指针移入时重播。触屏上忽略移入。 */
  interactive?: boolean
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

function coarsePointer() {
  return window.matchMedia("(pointer: coarse)").matches
}

const container: Variants = {
  hidden: {},
  show: {
    transition: {
      staggerChildren: 0.03,
    },
  },
}

const item: Variants = {
  hidden: { opacity: 0, y: 12, filter: "blur(6px)" },
  show: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: 0.45, ease: [0.22, 1, 0.36, 1] },
  },
}

function SplitText({
  text,
  delay = 0,
  by = "char",
  className,
  loop = false,
  interactive = false,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: SplitTextProps) {
  const reduced = usePrefersReducedMotion()
  const [replay, setReplay] = React.useState(0)
  const pieces = React.useMemo(
    () => (by === "word" ? text.split(/(\s+)/) : Array.from(text)),
    [by, text],
  )
  const style: React.CSSProperties = {}
  if (fontSize !== undefined) style.fontSize = fontSize
  if (fontWeight !== undefined) style.fontWeight = fontWeight
  if (letterSpacing !== undefined) style.letterSpacing = `${letterSpacing}em`
  if (align !== undefined) style.textAlign = align

  return (
    <motion.span
      key={replay}
      data-slot="split-text"
      className={cn("inline-flex flex-wrap", className)}
      style={Object.keys(style).length > 0 ? style : undefined}
      variants={container}
      initial={reduced ? false : "hidden"}
      animate="show"
      transition={reduced ? { duration: 0, delayChildren: 0 } : { delayChildren: delay }}
      onAnimationComplete={() => {
        if (loop && !reduced) setReplay((current) => current + 1)
      }}
      onPointerEnter={() => {
        if (reduced || !interactive || coarsePointer()) return
        setReplay((current) => current + 1)
      }}
    >
      {pieces.map((piece, index) => (
        <motion.span
          key={`${piece}-${index}`}
          variants={item}
          className="inline-block"
          transition={
            reduced ? { duration: 0 } : { duration: 0.45, ease: [0.22, 1, 0.36, 1] }
          }
        >
          {piece === " " ? "\u00A0" : piece}
        </motion.span>
      ))}
    </motion.span>
  )
}

export { SplitText }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { textStyle } from "@/lib/text-style"
import { cn } from "@/lib/utils"

export interface SpoilerTextProps {
  text: string
  className?: string
  /** 遮挡粒子数量。不传则 90。 */
  count?: number
  /** 粒子抖动速度倍率。不传则 1。 */
  speed?: number
  color?: string
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

interface Speck {
  x: number
  y: number
  vx: number
  vy: number
  life: number
}

function SpoilerText({
  text,
  className,
  count,
  speed,
  color,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: SpoilerTextProps) {
  const reduced = usePrefersReducedMotion()
  const [revealed, setRevealed] = React.useState(false)
  const hostRef = React.useRef<HTMLButtonElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const specks = React.useRef<Speck[]>([])
  const active = useAnimationActive(hostRef)
  const visible = revealed || reduced
  const speckCount = Math.max(1, Math.round(count ?? 90))
  const pace = speed === undefined || !Number.isFinite(speed) ? 1 : speed

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || visible || !active) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return
    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect()
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = width * dpr
      canvas.height = height * dpr
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      specks.current = Array.from({ length: speckCount }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: 0,
        vy: 0,
        life: 1,
      }))
    }
    resize()
    let frame = 0
    const tick = () => {
      const { width, height } = canvas.getBoundingClientRect()
      ctx.clearRect(0, 0, width, height)
      for (const speck of specks.current) {
        speck.x += (Math.random() - 0.5) * 0.8 * pace
        speck.y += (Math.random() - 0.5) * 0.8 * pace
        ctx.fillStyle =
          color === undefined
            ? `color-mix(in oklab, var(--foreground) ${40 + speck.life * 40}%, transparent)`
            : color
        ctx.fillRect(speck.x, speck.y, 2.2, 2.2)
      }
      frame = window.requestAnimationFrame(tick)
    }
    frame = window.requestAnimationFrame(tick)
    return () => window.cancelAnimationFrame(frame)
  }, [active, color, pace, speckCount, visible])

  const reveal = () => {
    if (reduced) {
      setRevealed(true)
      return
    }
    const canvas = canvasRef.current
    const ctx = canvas?.getContext("2d")
    if (!canvas || !ctx) {
      setRevealed(true)
      return
    }
    const { width, height } = canvas.getBoundingClientRect()
    specks.current = specks.current.map((speck) => ({
      ...speck,
      vx: (speck.x - width / 2) * 0.08,
      vy: (speck.y - height / 2) * 0.08,
    }))
    let steps = 0
    const burst = () => {
      ctx.clearRect(0, 0, width, height)
      for (const speck of specks.current) {
        speck.x += speck.vx
        speck.y += speck.vy
        speck.life *= 0.9
        ctx.globalAlpha = speck.life
        ctx.fillRect(speck.x, speck.y, 2.2, 2.2)
      }
      steps += 1
      if (steps < 18) window.requestAnimationFrame(burst)
      else setRevealed(true)
    }
    burst()
  }

  return (
    <button
      ref={hostRef}
      type="button"
      onClick={reveal}
      className={cn("relative inline-block rounded-md px-2 py-1 text-left", className)}
      aria-label={visible ? text : "点击揭示隐藏文本"}
    >
      <span className={cn(!visible && "opacity-0")} style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}>
        {text}
      </span>
      {!visible ? <canvas ref={canvasRef} className="absolute inset-0 size-full cursor-pointer" /> : null}
    </button>
  )
}

export { SpoilerText }

