export interface StarFavoriteToggleProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "color"> {
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
  /** 收藏后的填充色。不传时使用主色。 */
  color?: string
}

export function StarFavoriteToggle({
  pressed,
  defaultPressed = false,
  onPressedChange,
  color = "var(--primary)",
  className,
  style,
  type = "button",
  ...props
}: StarFavoriteToggleProps) {
  const reduced = usePrefersReducedMotion()
  const [uncontrolled, setUncontrolled] = useState(defaultPressed)
  const on = pressed ?? uncontrolled
  const painted = { "--star-color": color, ...style } as CSSProperties

  return (
    <button
      {...props}
      aria-label={props["aria-label"] ?? "收藏"}
      aria-pressed={on}
