import { motion, useMotionValue, useTransform } from "motion/react"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface StickyGridScrollProps {
  className?: string
  intensity?: number
  speed?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

const TILES = [
  { id: "a", label: "01", hue: 262 },
  { id: "b", label: "02", hue: 200 },
  { id: "c", label: "03", hue: 24 },
  { id: "d", label: "04", hue: 330 },
  { id: "e", label: "05", hue: 152 },
  { id: "f", label: "06", hue: 48 },
  { id: "g", label: "07", hue: 210 },
  { id: "h", label: "08", hue: 280 },
  { id: "i", label: "09", hue: 12 },
]

function Tile({ tile, hero = false }: { tile: (typeof TILES)[number]; hero?: boolean }) {
  return (
    <div
      className={cn("flex items-end rounded-xl p-3 text-sm font-medium text-white", hero ? "min-h-28 flex-1" : "h-24")}
      style={{ background: `linear-gradient(145deg, hsl(${tile.hue} 55% 32%), hsl(${tile.hue} 75% 52%))` }}
    >
      {tile.label}
    </div>
  )
}

function StickyGridScroll({ className, intensity, speed }: StickyGridScrollProps) {
  const reduced = usePrefersReducedMotion()
  const progress = useMotionValue(0)
  const rate = pace(speed)
  const shaped = useTransform(progress, (value) =>
    rate === 1 ? value : Math.pow(Math.min(Math.max(value, 0), 1), rate),
  )
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const leftY = useTransform(shaped, [0, 1], gain === 1 ? [24, -80] : [24 * gain, -80 * gain])
  const rightY = useTransform(shaped, [0, 1], gain === 1 ? [-12, 64] : [-12 * gain, 64 * gain])
  const endScale = gain === 1 ? 3.8 : 1 + (3.8 - 1) * gain
  const scale = useTransform(shaped, [0.12, 0.9], [1, endScale])

  const onScroll = (event: React.UIEvent<HTMLDivElement>) => {
    const element = event.currentTarget
    const max = element.scrollHeight - element.clientHeight
    progress.set(max <= 0 ? 0 : element.scrollTop / max)
  }

  return (
    <div
      data-slot="sticky-grid-scroll"
      tabIndex={0}
      aria-label="钉住的图片网格。滚动时两侧错位，中间图片放大到铺满。"
      className={cn("h-96 w-full overflow-auto rounded-xl border bg-background outline-none focus-visible:ring-2 focus-visible:ring-primary", className)}
      onScroll={onScroll}
    >
      <div className="h-[190vh]">
        <div className="sticky top-0 grid h-96 grid-cols-3 gap-3 overflow-hidden p-4">
          {[
            { tiles: TILES.slice(0, 3), motionY: leftY, center: false },
            { tiles: TILES.slice(3, 6), motionY: undefined, center: true },
            { tiles: TILES.slice(6, 9), motionY: rightY, center: false },
          ].map((column) => (
            <motion.div
              key={column.tiles.map((tile) => tile.id).join("-")}
              className="flex flex-col gap-3"
              style={reduced || !column.motionY ? undefined : { y: column.motionY }}
            >
              {column.tiles.map((tile, index) =>
                column.center && index === 1 ? (
                  <motion.div key={tile.id} className="z-10 origin-center" style={reduced ? undefined : { scale }}>
                    <Tile tile={tile} hero />
                  </motion.div>
                ) : (
                  <Tile key={tile.id} tile={tile} />
                ),
              )}
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  )
}

export { StickyGridScroll }

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"

import { StickyNoteBoard } from "./sticky-note-board"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
})

afterEach(() => {
  cleanup()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function note(name: string) {
  return screen.getByRole("button", { name })
}

test("默认贴出三张便利贴", () => {
  render(<StickyNoteBoard />)
  expect(note("先写标题")).toHaveStyle({ left: "24px", top: "28px" })
  expect(note("留白")).toBeInTheDocument()
  expect(note("明天再改")).toBeInTheDocument()
})

test("方向键立刻挪动便利贴并回调", () => {
  const onMove = vi.fn()
  render(<StickyNoteBoard onMove={onMove} />)
  fireEvent.keyDown(note("先写标题"), { key: "ArrowRight" })
  expect(onMove).toHaveBeenCalledWith("title", 48, 28)
  expect(note("先写标题")).toHaveStyle({ left: "48px" })
  expect(queue.size).toBe(0)
})

test("松手后惯性继续滑一段，停下时回调最终位置", () => {
  const onMove = vi.fn()
  render(<StickyNoteBoard onMove={onMove} />)
  const pad = note("留白")
  fireEvent.pointerDown(pad, { clientX: 0, clientY: 0, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerMove(pad, { clientX: 48, clientY: 8, pointerId: 1, timeStamp: 20 })
  fireEvent.pointerUp(pad, { clientX: 48, clientY: 8, pointerId: 1, timeStamp: 32 })
  expect(onMove).not.toHaveBeenCalled()
  pump(24)
  expect(onMove).toHaveBeenCalledTimes(1)
  const [id, x, y] = onMove.mock.calls[0] as [string, number, number]
  expect(id).toBe("space")
  expect(x).toBeGreaterThan(168 + 48)
  expect(y).toBeGreaterThan(76)
})

test("触屏拖动后同样带惯性", () => {
  const onMove = vi.fn()
  render(<StickyNoteBoard onMove={onMove} />)
  const pad = note("明天再改")
  fireEvent.pointerDown(pad, { button: 0, clientX: 0, clientY: 0, pointerId: 4, pointerType: "touch", timeStamp: 0 })
  fireEvent.pointerUp(pad, { button: 0, clientX: 36, clientY: -12, pointerId: 4, pointerType: "touch", timeStamp: 30 })
  pump(24)
  expect(onMove).toHaveBeenCalledTimes(1)
  expect(onMove.mock.calls[0]?.[0]).toBe("later")
})

test("减弱动效时松手就停在落点，不倾斜，也不申请动画帧", () => {
  reduceMotion = true
  const onMove = vi.fn()
  render(<StickyNoteBoard onMove={onMove} />)
  expect(document.querySelector("[data-slot='sticky-note-board']")).toHaveAttribute("data-reduced", "true")
  const pad = note("先写标题")
  fireEvent.pointerDown(pad, { clientX: 0, clientY: 0, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerMove(pad, { clientX: 40, clientY: 10, pointerId: 1, timeStamp: 20 })
  fireEvent.pointerUp(pad, { clientX: 40, clientY: 10, pointerId: 1, timeStamp: 40 })
  expect(onMove).toHaveBeenCalledWith("title", 64, 38)
  expect(pad.style.transform).not.toContain("rotate")
  expect(queue.size).toBe(0)
})

"use client"

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface StickyNote {
  id: string
  text: string
  x: number
  y: number
}

export interface StickyNoteBoardProps {
  notes?: readonly StickyNote[]
  onMove?: (id: string, x: number, y: number) => void
  color?: string
  size?: number
  duration?: number
  tilt?: number
  className?: string
}

const DEFAULT_NOTES: readonly StickyNote[] = [
  { id: "title", text: "先写标题", x: 24, y: 28 },
  { id: "space", text: "留白", x: 168, y: 76 },
  { id: "later", text: "明天再改", x: 72, y: 168 },
]

interface Origin {
  x: number
  y: number
  nx: number
  ny: number
  t: number
}

interface Glide {
  id: string
  x: number
  y: number
  vx: number
  vy: number
}

function tiltOf(vx: number, gain: number) {
  return Math.max(-18, Math.min(18, vx * gain))
}

function nudge(key: string) {
  if (key === "ArrowLeft") return { x: -24, y: 0 }
  if (key === "ArrowRight") return { x: 24, y: 0 }
  if (key === "ArrowUp") return { x: 0, y: -24 }
  if (key === "ArrowDown") return { x: 0, y: 24 }
  return null
}

function StickyNoteBoard({
  notes = DEFAULT_NOTES,
  onMove,
  color,
  size = 148,
  duration = 640,
  tilt = 12,
  className,
}: StickyNoteBoardProps) {
  const reduced = usePrefersReducedMotion()
  const [board, setBoard] = useState<readonly StickyNote[]>(notes)
  const [dragId, setDragId] = useState<string | null>(null)
  const [glideId, setGlideId] = useState<string | null>(null)
  const [rotation, setRotation] = useState(0)
  const origin = useRef<Origin | null>(null)
  const glide = useRef<Glide | null>(null)
  const onMoveRef = useRef(onMove)
  const reducedRef = useRef(reduced)
  const durationRef = useRef(duration)
  const tiltRef = useRef(tilt)
  useEffect(() => {
    onMoveRef.current = onMove
    reducedRef.current = reduced
    durationRef.current = duration
    tiltRef.current = tilt
  })
  const paperColor = color ?? "var(--card)"

  function settle(id: string, x: number, y: number) {
    glide.current = null
    setGlideId(null)
    setRotation(0)
    setBoard((prev) => prev.map((note) => (note.id === id ? { ...note, x, y } : note)))
    onMoveRef.current?.(id, x, y)
  }

  useEffect(() => {
    const current = glide.current
    if (!current) return
    if (reduced) {
      settle(current.id, current.x, current.y)
      return
    }
    let x = current.x
    let y = current.y
    let vx = current.vx
    let vy = current.vy
    let last = 0
    let elapsed = 0
    let raf = 0
    const step = (now: number) => {
      if (reducedRef.current) {
        settle(current.id, x, y)
        return
      }
      const dt = last === 0 ? 16 : Math.min(32, Math.max(0, now - last))
      last = now
      elapsed += dt
      const keep = Math.exp(-dt / Math.max(120, durationRef.current))
      vx *= keep
      vy *= keep
      x += vx * dt
      y += vy * dt
      const speed = Math.hypot(vx, vy)
      if (speed < 0.08 || elapsed >= durationRef.current) {
        settle(current.id, x, y)
        return
      }
      setRotation(tiltOf(vx, tiltRef.current))
      setBoard((prev) => prev.map((note) => (note.id === current.id ? { ...note, x, y } : note)))
      raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [glideId, reduced])

  function onPointerDown(event: ReactPointerEvent<HTMLButtonElement>, note: StickyNote) {
    if (event.pointerType === "mouse" && event.button !== 0) return
    event.currentTarget.setPointerCapture?.(event.pointerId)
    if (glide.current) settle(glide.current.id, glide.current.x, glide.current.y)
    origin.current = { x: event.clientX, y: event.clientY, nx: note.x, ny: note.y, t: event.timeStamp }
    setDragId(note.id)
    setRotation(0)
  }

  function onPointerMove(event: ReactPointerEvent<HTMLButtonElement>, id: string) {
    const start = origin.current
    if (!start || dragId !== id) return
    const dx = event.clientX - start.x
    const dy = event.clientY - start.y
    const dt = Math.max(16, event.timeStamp - start.t)
    setRotation(reduced ? 0 : tiltOf(dx / dt, tilt))
    setBoard((prev) => prev.map((note) => (note.id === id ? { ...note, x: start.nx + dx, y: start.ny + dy } : note)))
  }

  function onPointerUp(event: ReactPointerEvent<HTMLButtonElement>, id: string) {
    const start = origin.current
    origin.current = null
    setDragId(null)
    if (!start) return
    const dx = event.clientX - start.x
    const dy = event.clientY - start.y
    const x = start.nx + dx
    const y = start.ny + dy
    const dt = Math.max(16, event.timeStamp - start.t)
    if (dx === 0 && dy === 0) {
      setRotation(0)
      return
    }
    if (reduced) {
      settle(id, x, y)
      return
    }
    glide.current = { id, x, y, vx: dx / dt, vy: dy / dt }
    setBoard((prev) => prev.map((note) => (note.id === id ? { ...note, x, y } : note)))
    setGlideId(id)
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>, note: StickyNote) {
    const step = nudge(event.key)
    if (!step) return
    event.preventDefault()
    settle(note.id, note.x + step.x, note.y + step.y)
  }

  return (
    <div
      className={cn("bg-muted/40 relative h-80 w-full overflow-hidden rounded-2xl", className)}
      data-reduced={reduced ? "true" : undefined}
      data-slot="sticky-note-board"
    >
      {board.map((note) => {
        const moving = dragId === note.id || glideId === note.id
        return (
          <button
            className={cn(
              "absolute touch-none rounded-sm px-3 py-2 text-left text-sm shadow-md select-none",
              "motion-reduce:transition-none",
              moving || reduced ? "transition-none" : "transition-transform duration-200",
            )}
            key={note.id}
            onKeyDown={(event) => onKeyDown(event, note)}
            onPointerCancel={() => {
              origin.current = null
              setDragId(null)
              setRotation(0)
            }}
            onPointerDown={(event) => onPointerDown(event, note)}
            onPointerMove={(event) => onPointerMove(event, note.id)}
            onPointerUp={(event) => onPointerUp(event, note.id)}
            style={{
              background: paperColor,
              color: "var(--card-foreground)",
              height: size * 0.8,
              left: note.x,
              top: note.y,
              transform: moving && note.id === (dragId ?? glideId) ? `rotate(${rotation}deg)` : undefined,
              width: size,
            }}
            type="button"
          >
            {note.text}
          </button>
        )
      })}
    </div>
  )
}

export { StickyNoteBoard }

