        node.setAttribute("d", `${d}Z`);
      }
      // The label sits where its layer is thickest, and holds its spot until another stretch is clearly thicker.
      const text = labels.current.get(line.key);
      if (!text) return;
      let best = 4;
      for (let j = 4; j < N - 4; j++) if (top[j]! - bottom[j]! > top[best]! - bottom[best]!) best = j;
      const held = spots.current.get(line.key);
      const j = held !== undefined && top[held]! - bottom[held]! >= (top[best]! - bottom[best]!) * .8 ? held : best;
      spots.current.set(line.key, j);
      const thickness = (top[j]! - bottom[j]!) / span * (height - PAD * 2) * s;
      const room = text.getComputedTextLength?.() ?? 60;
      const x = clamp(xs[j]!, room / 2 + 6, w - room / 2 - 6);
      text.setAttribute("x", x.toFixed(1));
      text.setAttribute("y", yAt((top[j]! + bottom[j]!) / 2, j).toFixed(1));
      text.style.opacity = thickness >= 19 && room + 16 < w ? "1" : "0";
    });
  }, [grow, height]);

  useLayoutEffect(() => {
    const node = plot.current;
    if (!node) return;
    const read = () => { width.current = node.clientWidth; setPlotWidth(node.clientWidth); paint(); };
    read();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(read);
    observer.observe(node);
    return () => observer.disconnect();
  }, [paint]);

  // New data blends every layer from the shape on screen; a layer that arrives grows out of the one below it.
  const morph = useRef<{ stop: () => void } | null>(null);
  useEffect(() => {
    const moves: { key: string; from: number[]; to: number[] }[] = [];
    for (const [key, to] of targets) {
      const from = shapes.current.get(key);
      if (!from || reduced) { shapes.current.set(key, to); continue; }
      moves.push({ key, from, to });
    }
    for (const key of [...shapes.current.keys()]) if (!targets.has(key)) shapes.current.delete(key);
    morph.current?.stop();
    if (!moves.length) { paint(); return; }
    morph.current = animate(0, 1, { ...settle, onUpdate: t => { for (const move of moves) shapes.current.set(move.key, move.from.map((value, j) => value + (move.to[j]! - value) * t)); paint(); }, onComplete: () => { for (const move of moves) shapes.current.set(move.key, move.to); paint(); } });
    return () => morph.current?.stop();
  }, [paint, reduced, targets]);

  // A hidden layer thins to nothing while the others close over it.
  const hiddenKey = hidden.join("|");
  useEffect(() => {
    for (const line of series) {
      const to = hidden.includes(line.key) ? 0 : 1;
      const track = presence.current.get(line.key);
      if (!track) { presence.current.set(line.key, { value: to, stop: null }); continue; }
      if (track.value === to) continue;
      track.stop?.();
      if (reduced) { track.value = to; track.stop = null; continue; }
      const controls = animate(track.value, to, { ...settle, onUpdate: value => { track.value = value; paint(); } });
      track.stop = () => controls.stop();
    }
    paint();
  }, [hiddenKey, paint, reduced, series.length]); // eslint-disable-line react-hooks/exhaustive-deps

  // The first time the chart is seen, the stream swells out of a hairline along its centre.
  useEffect(() => {
    if (empty) return;
    if (reduced) { grow.jump(1); paint(); return; }
    if (!inView || grow.get() >= 1) return;
    const controls = animate(grow, 1, { ...swell, onUpdate: paint });
    return () => controls.stop();
  }, [empty, grow, inView, paint, reduced]);

  // The crosshair glides between points; the tooltip follows on its own spring and never leaves the plot.
  const cursor = useMotionValue(0);
  const cursorSpring = useSpring(cursor, follow);
  const tipX = useMotionValue(0), tipY = useMotionValue(0);
  const tipSpringX = useSpring(tipX, follow), tipSpringY = useSpring(tipY, follow);
  const wasActive = useRef(false);
  useLayoutEffect(() => {
    const bubble = tip.current, w = width.current;
    if (index === null || !bubble || !w) { wasActive.current = false; return; }
    const x = last > 0 ? (index / last) * w : w / 2;
    let y = hover?.y ?? null;
    const f = frame.current;
    if (y === null && f && activeKey) {
      const i = series.findIndex(line => line.key === activeKey), j = Math.round((x / w) * (N - 1));
      if (i >= 0) y = f.toY((f.upper[i]![j]! + f.lower[i]![j]!) / 2);
    }
    const tw = bubble.offsetWidth, th = bubble.offsetHeight;
    let left = x + GAP;
    if (left + tw > w) left = x - GAP - tw;
    const top = clamp((y ?? height / 2) - th / 2, 0, Math.max(0, height - th));
    const instant = !wasActive.current || reduced;
    cursor.set(x); tipX.set(clamp(left, 0, Math.max(0, w - tw))); tipY.set(top);
    if (instant) { cursorSpring.jump(x); tipSpringX.jump(tipX.get()); tipSpringY.jump(top); }
    wasActive.current = true;
  });

  const onActive = useRef(onActiveChange);
  useLayoutEffect(() => { onActive.current = onActiveChange; });
  useEffect(() => { onActive.current?.(index, activeKey); }, [index, activeKey]);

  // The layer under the pointer, found in the frame that is on screen.
  const read = (clientX: number, clientY: number): Hover | null => {
    const rect = plot.current?.getBoundingClientRect(), f = frame.current;
    if (!rect?.width || empty) return null;
    const share = clamp((clientX - rect.left) / rect.width, 0, 1), y = clientY - rect.top;
    const at = last > 0 ? Math.round(share * last) : 0, j = Math.round(share * (N - 1));
    let key: string | null = null;
    if (f) series.forEach((line, i) => { if (hidden.includes(line.key)) return; const top = f.toY(f.upper[i]![j]!), bottom = f.toY(f.lower[i]![j]!); if (y >= top - 1 && y <= bottom + 1) key = line.key; });
    return { index: at, key, y };
  };
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => { if (event.pointerType === "mouse" || event.buttons) setHover(read(event.clientX, event.clientY)); };
  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => { if (event.pointerType !== "mouse") event.currentTarget.setPointerCapture?.(event.pointerId); setHover(read(event.clientX, event.clientY)); };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (empty) return;
    if (event.key === "Escape" && hover) { event.preventDefault(); setHover(null); return; }
    const from = index ?? last;
    const keys = visible.map(line => line.key), at = activeKey ? keys.indexOf(activeKey) : -1;
    const page = Math.max(1, Math.round(data.length / 6));
    const moves: Record<string, () => Hover> = {
      ArrowLeft: () => ({ index: clamp(from - 1, 0, last), key: activeKey, y: null }),
      ArrowRight: () => ({ index: clamp(index === null ? last : from + 1, 0, last), key: activeKey, y: null }),
      PageDown: () => ({ index: clamp(from - page, 0, last), key: activeKey, y: null }),
      PageUp: () => ({ index: clamp(from + page, 0, last), key: activeKey, y: null }),
      Home: () => ({ index: 0, key: activeKey, y: null }),
      End: () => ({ index: last, key: activeKey, y: null }),
      ArrowUp: () => ({ index: from, key: keys[at < 0 ? keys.length - 1 : Math.min(keys.length - 1, at + 1)] ?? null, y: null }),
      ArrowDown: () => ({ index: from, key: keys[at < 0 ? 0 : Math.max(0, at - 1)] ?? null, y: null }),
    };
    const move = moves[event.key];
    if (!move) return;
    event.preventDefault();
    setHover(move());
  };

  const format = (value: number, line: StreamgraphSeries) => `${formatValue ? formatValue(value, line) : grouped.format(value)}${unit ? ` ${unit}` : ""}`;
  const reading = index === null ? null : data[index];
  const total = (datum: StreamgraphDatum) => visible.reduce((sum, line) => sum + Math.max(0, datum.values[line.key] ?? 0), 0);
  const announce = reading ? `${reading.label}. ${activeKey ? `${series.find(line => line.key === activeKey)?.label} ${format(reading.values[activeKey] ?? 0, series.find(line => line.key === activeKey)!)}, ` : ""}${visible.length} layers, ${grouped.format(total(reading))}${unit ? ` ${unit}` : ""} in total` : "";
  const summary = empty ? `${label}. ${emptyLabel}.` : `${label}, ${data[0]!.label} to ${data[last]!.label}. ${visible.map(line => `${line.label}, latest ${format(data[last]!.values[line.key] ?? 0, line)}`).join(". ")}.`;
  const picks = axisPicks(data, plotWidth);
  const tipLeft = reduced ? tipX : tipSpringX, tipTop = reduced ? tipY : tipSpringY;

  return <ArcQuiet.Provider value={!arcLive}><ArcStyle /><figure data-slot="streamgraph" data-reduced={reduced ? "true" : "false"} data-motion={arcLive && !reduced ? "on" : "off"}  ref={figure} className={[styles.figure, className].filter(Boolean).join(" ")} aria-label={label}>
    {legend && series.length > 1 && <div className={styles.legend} role="group" aria-label={`${label} layers`} onPointerLeave={() => setLegendKey(null)}>
      {series.map((line, at) => <button key={line.key} type="button" className={styles.toggle} aria-pressed={!hidden.includes(line.key)} data-active={activeKey === line.key || undefined} data-dim={(activeKey !== null && activeKey !== line.key) || undefined} onClick={() => toggle(line.key)}
        onPointerEnter={event => { if (event.pointerType === "mouse") setLegendKey(line.key); }} onFocus={event => { if (event.currentTarget.matches(":focus-visible")) setLegendKey(line.key); }} onBlur={() => setLegendKey(null)}
        style={{ "--series": colorOf(line, at) } as CSSProperties}>
        <span className={styles.swatch} aria-hidden="true" />
        <span className={styles.toggleLabel}>{line.label}</span>
      </button>)}
    </div>}
    <div className={styles.chart} data-active={index !== null || undefined} data-layer={activeKey ? true : undefined}>
      <div ref={plot} className={styles.plot} style={{ height }} role="group" tabIndex={empty ? -1 : 0} aria-roledescription="stream graph" aria-label={`${label}. Use left and right arrows to move through time, up and down to change layer.`}
        onPointerMove={onPointerMove} onPointerDown={onPointerDown} onPointerUp={event => { if (event.pointerType !== "mouse") setHover(null); }} onPointerCancel={() => setHover(null)} onPointerLeave={event => { if (event.pointerType === "mouse") setHover(null); }}
        onKeyDown={onKeyDown} onBlur={() => setHover(null)} onFocus={event => { if (event.currentTarget.matches(":focus-visible") && !empty) setHover(current => current ?? { index: last, key: null, y: null }); }}>
        <svg className={styles.svg} width="100%" height={height} aria-hidden="true" focusable="false"><title>{label}</title>
          {series.map((line, at) => <path key={line.key} ref={node => { if (node) paths.current.set(line.key, node); else paths.current.delete(line.key); }} className={styles.layer} data-active={activeKey === line.key || undefined} data-custom={line.color ? true : undefined} style={{ "--series": colorOf(line, at) } as CSSProperties} />)}
          <motion.line className={styles.crosshair} x1={0} x2={0} y1={0} y2={height} style={{ x: reduced ? cursor : cursorSpring }} />
          {directLabels && series.map(line => <text key={line.key} ref={node => { if (node) labels.current.set(line.key, node); else labels.current.delete(line.key); }} className={styles.label} data-active={activeKey === line.key || undefined} data-custom={line.color ? true : undefined} data-hidden={hidden.includes(line.key) || undefined} data-dim={(activeKey !== null && activeKey !== line.key) || undefined} textAnchor="middle" dominantBaseline="central">{line.label}</text>)}
        </svg>
        <motion.div ref={tip} className={styles.tooltip} style={{ x: tipLeft, y: tipTop }} aria-hidden="true">
          <p className={styles.tipTitle}>{reading?.label ?? ""}</p>
          {stackOrder(series.length, offset).reverse().map(at => series[at]!).filter(line => !hidden.includes(line.key)).map(line => <p key={line.key} className={styles.tipRow} data-active={activeKey === line.key || undefined} data-dim={(activeKey !== null && activeKey !== line.key) || undefined} style={{ "--series": colorOf(line, series.indexOf(line)) } as CSSProperties}>
            <span className={styles.tipSwatch} />
            <span className={styles.tipName}>{line.label}</span>
            <span className={styles.tipValue}>{reading ? format(reading.values[line.key] ?? 0, line) : ""}</span>
          </p>)}
        </motion.div>
        {(empty || visible.length === 0) && <p className={styles.message}>{empty ? emptyLabel : "Choose a layer to show"}</p>}
      </div>
      <div className={styles.axis} aria-hidden="true">
        {picks.map(at => { const share = last > 0 ? at / last : .5; const item = data[at]!; return <span key={`${item.key}`} className={styles.axisLabel} style={{ left: `${share * 100}%`, translate: `${-share * 100}% 0` }}>{item.axisLabel}</span>; })}
      </div>
    </div>
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{announce}</p>
    <p className={styles.srOnly}>{summary}</p>
    {!empty && <div className={styles.srOnly}><table>
      <caption>{label}</caption>
      <thead><tr><th scope="col">{categoryLabel}</th>{series.map(line => <th key={line.key} scope="col">{line.label}</th>)}</tr></thead>
      <tbody>{data.map(item => <tr key={item.key}><th scope="row">{item.label}</th>{series.map(line => <td key={line.key}>{format(item.values[line.key] ?? 0, line)}</td>)}</tr>)}</tbody>
    </table></div>}
  </figure></ArcQuiet.Provider>;
}

export default Streamgraph;

"use client";

// Ported from ns-ui (MIT, (c) 2026 Nikolas Sapalidis) — https://github.com/nikolas-sapa/ns-ui/blob/main/registry/loud/success-plumb-bob/component.tsx

import {
  useEffect,
  useRef,
  useState,
} from "react";

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useAnimationActive } from "@/hooks/use-animation-active";
import type { RefObject } from "react";

type NsJob = { token: number; cb: (now: number) => void; raf: number };
type NsApi = {
  requestFrame: (cb: (now: number) => void) => number;
  cancelFrame: (id: number | null | undefined) => void;
  motionNow: () => number;
};

const nsApi: NsApi = {
  requestFrame: (cb) => requestAnimationFrame((t) => cb(t)),
  cancelFrame: (id) => {
    if (id) cancelAnimationFrame(id);
  },
  motionNow: () => performance.now(),
};

function nsRequestFrame(cb: (now: number) => void) {
  return nsApi.requestFrame(cb);
}
function nsCancelFrame(id: number | null | undefined) {
  nsApi.cancelFrame(id);
}
function nsMotionNow() {
  return nsApi.motionNow();
}

function useNsBind(rootRef: RefObject<HTMLElement | null>) {
  const reduced = usePrefersReducedMotion();
  const live = useAnimationActive(rootRef as RefObject<Element | null>);
  const liveRef = useRef(live);
  const reducedRef = useRef(reduced);
  const holdRef = useRef(0);
  const offsetRef = useRef(0);
  const jobsRef = useRef(new Map<number, NsJob>());
  const seqRef = useRef(1);

  const motionNow = () => {
    const raw = performance.now();
    if (!liveRef.current) {
      if (holdRef.current === 0) holdRef.current = raw;
      return holdRef.current - offsetRef.current;
    }
    if (holdRef.current !== 0) {
      offsetRef.current += raw - holdRef.current;
      holdRef.current = 0;
    }
    return raw - offsetRef.current;
  };

  const requestFrame = (cb: (now: number) => void) => {
    const token = seqRef.current++;
    const job: NsJob = { token, cb, raf: 0 };
    jobsRef.current.set(token, job);
    const kick = () => {
      if (!liveRef.current) {
        if (holdRef.current === 0) holdRef.current = performance.now();
        job.raf = 0;
        return;
      }
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          if (holdRef.current === 0) holdRef.current = performance.now();
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    };
    kick();
    return token;
  };

  const cancelFrame = (id: number | null | undefined) => {
    if (id == null) return;
    const job = jobsRef.current.get(id);
    if (!job) return;
    if (job.raf) cancelAnimationFrame(job.raf);
    jobsRef.current.delete(id);
  };

  useEffect(() => {
    liveRef.current = live;
    reducedRef.current = reduced;
  }, [live, reduced]);

  useEffect(() => {
    nsApi.requestFrame = requestFrame;
    nsApi.cancelFrame = cancelFrame;
    nsApi.motionNow = motionNow;
  });

  useEffect(() => {
    if (!live) return;
    for (const job of [...jobsRef.current.values()]) {
      if (job.raf) continue;
      const { token, cb } = job;
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    }
  }, [live]);

  useEffect(
    () => () => {
      for (const job of jobsRef.current.values()) {
        if (job.raf) cancelAnimationFrame(job.raf);
      }
      jobsRef.current.clear();
    },
    [],
  );

  return { reduced, live, motionOn: live && !reduced, requestFrame, cancelFrame, motionNow };
}

function NsPause({ slot }: { slot: string }) {
  return (
    <style>{`[data-slot="${slot}"][data-motion="off"],[data-slot="${slot}"][data-motion="off"] *{animation-play-state:paused !important}`}</style>
  );
}

// ---------------------------------------------------------------------------
// PlumbTrue — a success moment built on a plumb bob instead of confetti or a
// checkmark draw. Pressing the trigger stands in for the real event (payment
// confirmed, deploy finished, form accepted) firing *before* any motion plays:
// the accessible announcement and onConfirm fire synchronously at the press,
// then a bob drops from a fixed anchor on a fine string (translateY, gravity
// ease-in, a hard stop at full string length — no bounce in the length
// itself), and the sudden stop kicks it into a pendulum swing (rotate about
// the anchor) that decays through a few honest diminishing oscillations
// (closed-form damped cosine, recomputed every frame — no keyframe list) back
// to hanging dead straight. The card carries a second, fixed vertical datum
// line at the same x as the anchor: while swinging, the string visibly
// diverges from it; the moment the swing decays to rest the two are
// collinear — that coincidence *is* the verification, not a separate symbol.
// Only then does a level line draw outward from the bob's tip in both
// directions (stroke-dashoffset, ease-out-expo) and the success text rises
// and fades onto it. Two faint echo copies of the string+bob, tinted via
// color-mix, trail the first swing and fade out — an optional motion-blur
// read, never load-bearing.
//
// The pendulum's continuous per-frame pose is written straight to SVG
// attributes/style via refs (no React state on that path); the few discrete
// phase changes (armed -> settled, live-region text, button label) go through
// React state since they render only a handful of times per mount. Reduced
// motion skips the drop/swing/echoes entirely and snaps straight to the
// settled pose — the level line and text are simply already there, per the
// brief's "reduced motion renders the bob at rest, line and text already
// placed." Every color is a var(--token) reference read straight off the
// cascade (SVG attribute values resolve CSS custom properties natively), so
// there is nothing to re-derive on theme change.
// ---------------------------------------------------------------------------

export interface PlumbTrueProps {
  /** small line above the trigger, shown only while pending */
  pendingCopy?: string;
  /** label on the trigger button before it's pressed */
  pendingLabel?: string;
  /** label shown on the button while the bob is dropping/swinging */
  armingLabel?: string;
  /** announced immediately (role=status) and set onto the level line at rest */
  successMessage?: string;
  /** label the same button carries once settled — the real next action */
  nextActionLabel?: string;
  /** fires synchronously at press, before any motion — this *is* the event */
  onConfirm?: () => void;
  /** fires when the settled button is pressed */
  onNextAction?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Phase = "pending" | "active" | "settled";

// -- geometry (SVG user units, viewBox 0 0 240 160) --------------------------
const VB_W = 240;
const VB_H = 160;
const ANCHOR_X = 120;
const ANCHOR_Y = 16;
const STRING_LEN = 92;
// bob: a small teardrop, local origin at its attach point, tip pointing down
const BOB_PATH = "M -6 4 A 6 6 0 1 1 6 4 Q 6 15 0 21 Q -6 15 -6 4 Z";
const BOB_TIP_Y = 21; // local y of the tip, relative to the bob's attach point
const LEVEL_Y = ANCHOR_Y + STRING_LEN + BOB_TIP_Y; // world y the level line draws at
const LEVEL_HALF = 84; // px the level line reaches left/right of center
const DATUM_TOP = 30;
const DATUM_BOTTOM = 126;

// -- timing/physics -----------------------------------------------------------
const DROP_MS = 200; // straight fall, ease-in, hard stop at STRING_LEN
const SWING_MS = 950; // pendulum decay window after the stop
const SWING_AMP = 15; // deg, deflection right at the stop (the "overshoot")
const SWING_PERIOD = 330; // ms per oscillation (~2.9 cycles over SWING_MS)
const SWING_TAU = 260; // ms, exponential decay time-constant
const ECHO_FADE_MS = 500; // ghost trail only reads during the first swing
const LEVEL_MS = 260; // ease-out-expo level-line draw
const TEXT_MS = 300; // success text fade + rise

function easeInQuad(t: number) {
  return t * t;
}

export function PlumbTrue({
  pendingCopy = "Order total $49.00",
  pendingLabel = "Confirm payment",
  armingLabel = "Confirming…",
  successMessage = "Payment confirmed",
  nextActionLabel = "View receipt",
  onConfirm,
  onNextAction,
  className = "",
}: PlumbTrueProps) {
  const nsRootRef = useRef<HTMLDivElement | null>(null);
  const nsMotion = useNsBind(nsRootRef as RefObject<HTMLElement | null>);
  const nsRequestFrame = nsMotion.requestFrame;
  const nsCancelFrame = nsMotion.cancelFrame;
  const nsMotionNow = nsMotion.motionNow;

  const [phase, setPhase] = useState<Phase>("pending");
  const [reduced, setReduced] = useState(false);
  const [live, setLive] = useState("");

  const phaseRef = useRef<Phase>("pending");
  const reducedRef = useRef(false);
  const rafRef = useRef(0);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const wasSettled = useRef(false);

  const groupRef = useRef<SVGGElement>(null);
  const stringRef = useRef<SVGLineElement>(null);
  const bobRef = useRef<SVGPathElement>(null);
  const echo1GroupRef = useRef<SVGGElement>(null);
  const echo1StringRef = useRef<SVGLineElement>(null);
  const echo1BobRef = useRef<SVGPathElement>(null);
  const echo2GroupRef = useRef<SVGGElement>(null);
  const echo2StringRef = useRef<SVGLineElement>(null);
  const echo2BobRef = useRef<SVGPathElement>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
      setReduced(mq.matches);
    };
    sync();
    mq.addEventListener("change", sync);
    return () => {
      mq.removeEventListener("change", sync);
      nsCancelFrame(rafRef.current);
    };
  }, []);

  // move focus onto the primary next action once settled, so a screen reader
  // (or a keyboard user who never looked away) lands where the flow expects
  useEffect(() => {
    if (phase === "settled" && !wasSettled.current) {
      wasSettled.current = true;
      buttonRef.current?.focus();
    }
  }, [phase]);

  function applyPose(l: number, thetaDeg: number) {
    const s = stringRef.current;
    const b = bobRef.current;
    const g = groupRef.current;
    if (s) s.setAttribute("y2", String(ANCHOR_Y + l));
    if (b) b.setAttribute("transform", `translate(${ANCHOR_X} ${ANCHOR_Y + l})`);
    if (g) g.style.transform = `rotate(${thetaDeg.toFixed(3)}deg)`;
  }

  function applyEcho(
    groupEl: SVGGElement | null,
    stringEl: SVGLineElement | null,
    bobEl: SVGPathElement | null,
    thetaDeg: number,
    opacity: number
  ) {
    if (stringEl) stringEl.setAttribute("y2", String(ANCHOR_Y + STRING_LEN));
    if (bobEl) bobEl.setAttribute("transform", `translate(${ANCHOR_X} ${ANCHOR_Y + STRING_LEN})`);
    if (groupEl) {
      groupEl.style.transform = `rotate(${thetaDeg.toFixed(3)}deg)`;
      groupEl.style.opacity = opacity.toFixed(3);
    }
  }

  function snapSettled() {
    applyPose(STRING_LEN, 0);
    applyEcho(echo1GroupRef.current, echo1StringRef.current, echo1BobRef.current, 0, 0);
    applyEcho(echo2GroupRef.current, echo2StringRef.current, echo2BobRef.current, 0, 0);
  }

  function startAnimation() {
    const start = nsMotionNow();
    const tick = (now: number) => {
      const elapsed = now - start;
      if (elapsed < DROP_MS) {
        const l = STRING_LEN * easeInQuad(elapsed / DROP_MS);
        applyPose(l, 0);
      } else if (elapsed < DROP_MS + SWING_MS) {
        const tt = elapsed - DROP_MS;
        const theta =
          SWING_AMP * Math.exp(-tt / SWING_TAU) * Math.cos((2 * Math.PI * tt) / SWING_PERIOD);
        applyPose(STRING_LEN, theta);

        const echoOpacity = Math.max(0, 1 - tt / ECHO_FADE_MS) * 0.2;
        for (const lag of [40, 80] as const) {
          const et = Math.max(0, tt - lag);
          const etheta =
            SWING_AMP * Math.exp(-et / SWING_TAU) * Math.cos((2 * Math.PI * et) / SWING_PERIOD);
          if (lag === 40) {
            applyEcho(echo1GroupRef.current, echo1StringRef.current, echo1BobRef.current, etheta, echoOpacity);
          } else {
            applyEcho(echo2GroupRef.current, echo2StringRef.current, echo2BobRef.current, etheta, echoOpacity * 0.6);
          }
        }
      } else {
        snapSettled();
        phaseRef.current = "settled";
        setPhase("settled");
        rafRef.current = 0;
        return;
      }
      rafRef.current = nsRequestFrame(tick);
    };
    rafRef.current = nsRequestFrame(tick);
  }

  function confirm() {
    if (phaseRef.current !== "pending") return; // irreversible: one press decides it
    phaseRef.current = "active";
    setPhase("active");
    // the real event happens now, in full, regardless of what the instrument
    // goes on to draw — announcement and callback are never gated on motion
    setLive(successMessage);
    onConfirm?.();
    if (reducedRef.current) {
      snapSettled();
      phaseRef.current = "settled";
      setPhase("settled");
    } else {
      startAnimation();
    }
  }

  function handleClick() {
    if (phaseRef.current === "pending") confirm();
    else if (phaseRef.current === "settled") onNextAction?.();
    // mid-swing presses are inert: the outcome is already decided
  }

  const settled = phase === "settled";
  const textTop = (LEVEL_Y / VB_H) * 100;
  const buttonLabel = phase === "pending" ? pendingLabel : settled ? nextActionLabel : armingLabel;

  return (
    <div ref={nsRootRef} data-slot="success-plumb-bob" data-reduced={nsMotion.reduced ? "true" : "false"} data-motion={nsMotion.motionOn ? "on" : "off"} className={`rounded-md border border-border bg-background p-6 ${className}`}>
      <NsPause slot="success-plumb-bob" />
      <div
        className="relative mx-auto mb-1 aspect-[240/160] w-full max-w-[220px]"
      >
        <svg
          viewBox={`0 0 ${VB_W} ${VB_H}`}
          className="absolute inset-0 h-full w-full"
          aria-hidden="true"
        >
          {/* mount bracket + pivot */}
          <line
            x1={ANCHOR_X - 15}
            y1={ANCHOR_Y - 8}
            x2={ANCHOR_X + 15}
            y2={ANCHOR_Y - 8}
            stroke="var(--border)"
            strokeWidth="1"
          />
          <circle cx={ANCHOR_X} cy={ANCHOR_Y} r="2" fill="var(--border)" />

          {/* etched vertical datum — the fixed reference the bob must agree with */}
          <line
            x1={ANCHOR_X}
            y1={DATUM_TOP}
            x2={ANCHOR_X}
            y2={DATUM_BOTTOM}
            stroke="var(--border)"
            strokeWidth="1"
            strokeDasharray="1 3"
          />
          <line x1={ANCHOR_X - 5} y1={DATUM_TOP} x2={ANCHOR_X + 5} y2={DATUM_TOP} stroke="var(--border)" strokeWidth="1" />
          <line
            x1={ANCHOR_X - 5}
            y1={DATUM_BOTTOM}
            x2={ANCHOR_X + 5}
            y2={DATUM_BOTTOM}
            stroke="var(--border)"
            strokeWidth="1"
          />

          {/* ghost echoes — faint motion-blur read on the first swing only */}
          <g ref={echo1GroupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px`, opacity: 0 }}>
            <line
              ref={echo1StringRef}
              x1={ANCHOR_X}
              y1={ANCHOR_Y}
              x2={ANCHOR_X}
              y2={ANCHOR_Y}
              stroke="color-mix(in srgb, var(--muted-foreground) 20%, transparent)"
              strokeWidth="1"
            />
            <path ref={echo1BobRef} d={BOB_PATH} fill="color-mix(in srgb, var(--foreground) 20%, transparent)" />
          </g>
          <g ref={echo2GroupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px`, opacity: 0 }}>
            <line
              ref={echo2StringRef}
              x1={ANCHOR_X}
              y1={ANCHOR_Y}
              x2={ANCHOR_X}
              y2={ANCHOR_Y}
              stroke="color-mix(in srgb, var(--muted-foreground) 20%, transparent)"
              strokeWidth="1"
            />
            <path ref={echo2BobRef} d={BOB_PATH} fill="color-mix(in srgb, var(--foreground) 20%, transparent)" />
          </g>

          {/* the bob itself: fine string + filled teardrop, rotating about the anchor */}
          <g ref={groupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px` }}>
            <line ref={stringRef} x1={ANCHOR_X} y1={ANCHOR_Y} x2={ANCHOR_X} y2={ANCHOR_Y} stroke="var(--muted-foreground)" strokeWidth="1" />
            <path ref={bobRef} d={BOB_PATH} fill="var(--foreground)" transform={`translate(${ANCHOR_X} ${ANCHOR_Y})`} />
          </g>

          {/* level line — draws outward from the tip in both directions once settled */}
          <line
            x1={ANCHOR_X}
            y1={LEVEL_Y}
            x2={ANCHOR_X - LEVEL_HALF}
            y2={LEVEL_Y}
            stroke="var(--foreground)"
            strokeWidth="1"
            strokeDasharray={LEVEL_HALF}
            strokeDashoffset={settled ? 0 : LEVEL_HALF}
            style={{ transition: reduced ? "none" : `stroke-dashoffset ${LEVEL_MS}ms cubic-bezier(0.16,1,0.3,1)` }}
          />
          <line
            x1={ANCHOR_X}
            y1={LEVEL_Y}
            x2={ANCHOR_X + LEVEL_HALF}
            y2={LEVEL_Y}
            stroke="var(--foreground)"
            strokeWidth="1"
            strokeDasharray={LEVEL_HALF}
            strokeDashoffset={settled ? 0 : LEVEL_HALF}
            style={{ transition: reduced ? "none" : `stroke-dashoffset ${LEVEL_MS}ms cubic-bezier(0.16,1,0.3,1)` }}
          />
        </svg>

        {/* real DOM success text — sits just below the level line, clear of the
            resting bob (which occupies the space directly above the tip), and
            rises the last 8px up into that resting spot as it fades in */}
        <div
          className="pointer-events-none absolute left-1/2 w-[85%] -translate-x-1/2 pt-2 text-center"
          style={{ top: `${textTop}%` }}
        >
          <span
            data-plumb-success
            aria-hidden={settled ? undefined : "true"}
            className="pointer-events-auto inline-block text-sm font-semibold text-foreground sm:text-base"
            style={{
              opacity: settled ? 1 : 0,
              transform: `translateY(${settled ? 0 : 8}px)`,
              transition: reduced ? "none" : `opacity ${TEXT_MS}ms ease-out, transform ${TEXT_MS}ms cubic-bezier(0.16,1,0.3,1)`,
            }}
          >
            {successMessage}
          </span>
        </div>
      </div>

      <p
        className="text-center text-sm text-muted-foreground"
        style={{ opacity: phase === "pending" ? 1 : 0, transition: "opacity 200ms ease-out" }}
      >
        {pendingCopy}
      </p>

      <div className="mt-4 flex justify-center">
        <button
          ref={buttonRef}
          type="button"
          onClick={handleClick}
          className="rounded-sm border border-border bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-border/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
        >
          {buttonLabel}
        </button>
      </div>

      {/* announced immediately at confirm() — never delayed for the instrument */}
      <p role="status" aria-live="polite" className="sr-only">
        {live}
      </p>
    </div>
  );
}

"use client"

// Ported from Cult UI (MIT) — https://github.com/nolly-studio/cult-ui/blob/main/apps/www/registry/default/ui/svg-bands.tsx

import { useId, useRef, type ReactNode } from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface SvgBandsProps {
  colors?: readonly string[]
  className?: string
  children?: ReactNode
}

const DEFAULT_COLORS = ["#38bdf8", "#a78bfa", "#f472b6"]

const BANDS = [
  "M-40,90 C80,10 180,150 320,40 C420,-20 520,120 640,70 L640,170 C500,210 400,90 280,150 C160,210 40,120 -40,180 Z",
  "M-40,130 C90,50 200,190 340,90 C460,10 540,160 640,110 L640,210 C520,250 430,140 310,190 C180,250 70,160 -40,220 Z",
  "M-40,40 C110,-20 210,120 360,20 C480,-40 560,100 640,50 L640,140 C530,190 420,70 290,130 C150,190 40,90 -40,130 Z",
]

function safeToken(raw: string) {
  const cleaned = raw.replace(/[^a-zA-Z0-9_-]/g, "")
  return cleaned || "bands"
}

function SvgBands({ colors = DEFAULT_COLORS, className, children }: SvgBandsProps) {
  const wrapRef = useRef<HTMLDivElement>(null)
  const reduced = usePrefersReducedMotion()
  const active = useAnimationActive(wrapRef)
  const token = safeToken(useId())
  const palette = colors.length > 0 ? colors : DEFAULT_COLORS
  const flowing = !reduced && active

  const css = `
@keyframes svg-bands-${token} {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-56px, 16px, 0); }
}
.svg-bands-${token} {
  animation: svg-bands-${token} 16s linear infinite;
  animation-play-state: ${flowing ? "running" : "paused"};
}
`

  return (
    <div
      ref={wrapRef}
      data-slot="svg-bands"
      data-reduced={reduced ? "true" : undefined}
      className={cn("relative h-56 w-full overflow-hidden rounded-xl bg-[#070b16]", className)}
    >
      <style>{css}</style>
      <svg viewBox="0 0 600 240" className="absolute inset-0 h-full w-full" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          {palette.map((color, index) => (
            <linearGradient id={`svg-band-${token}-${index}`} key={color + index} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0" stopColor={color} stopOpacity="0.15" />
              <stop offset="0.5" stopColor={color} stopOpacity="0.85" />
              <stop offset="1" stopColor={palette[(index + 1) % palette.length]} stopOpacity="0.2" />
            </linearGradient>
          ))}
        </defs>
        {BANDS.map((path, index) => (
          <path
            key={path}
            d={path}
            fill={`url(#svg-band-${token}-${index % palette.length})`}
            className={reduced ? undefined : `svg-bands-${token}`}
            style={{ animationDelay: `${index * -3}s` }}
          />
        ))}
      </svg>
      {children ? <div className="relative z-10 h-full">{children}</div> : null}
    </div>
  )
}

export { SvgBands }

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/svg-clip-mask/index.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"


const HOVER_QUERY = "(hover: hover) and (pointer: fine)";

function subscribeHover(onStoreChange: () => void) {
  const media = window.matchMedia(HOVER_QUERY);
  media.addEventListener("change", onStoreChange);
  return () => media.removeEventListener("change", onStoreChange);
}

function hoverSnapshot() {
  return window.matchMedia(HOVER_QUERY).matches;
}

function useHoverCapable() {
  return useSyncExternalStore(subscribeHover, hoverSnapshot, () => false);
}

import {
  motion,
  useMotionValueEvent,
  useScroll,
} from "motion/react";
import {
  type ReactNode,
  type RefObject,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const EASE_MOVE = [0.645, 0.045, 0.355, 1] as const;
const TRANSITION_DURATION = 0.3;
const DEFAULT_MORPH_DURATION = 4;
// The mask has to finish opening while the frame is still in view; the full
// enter-to-exit range parks the fully-revealed state off-screen.
const DEFAULT_SCROLL_OFFSET: ScrollOffset = ["start 0.9", "end 0.6"];

const PRESET_PATHS = {
  arch: "M0,1 L0,0.4 C0,0.18 0.18,0 0.5,0 C0.82,0 1,0.18 1,0.4 L1,1 Z",
  blob: "M0.5,0.02 C0.75,0.02 0.98,0.25 0.98,0.5 C0.98,0.75 0.75,0.98 0.5,0.98 C0.25,0.98 0.02,0.75 0.02,0.5 C0.02,0.25 0.25,0.02 0.5,0.02 Z",
  diamond: "M0.5,0 L1,0.5 L0.5,1 L0,0.5 Z",
  wave: "M0,0.3 C0.25,0.05 0.75,0.55 1,0.3 L1,1 L0,1 Z",
} as const;

export type SvgClipMaskShape = "blob" | "arch" | "diamond" | "wave" | "custom";
export type SvgClipMaskAnimate = "none" | "morph" | "scroll" | "hover";

export interface SvgClipMaskProps {
  /**
   * "morph" cycles through morphPaths forever, "scroll" steps through them as
   * the container scrolls, "hover" swaps to morphPaths[0] on hover.
   */
  animate?: SvgClipMaskAnimate;
  children: ReactNode;
  className?: string;
  /** Ref to a scrollable ancestor that drives "scroll" mode instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /** Seconds for one full "morph" loop. */
  duration?: number;
  /**
   * Paths to cycle between for "morph"/"scroll"/"hover". They must all share
   * the same command structure (same sequence of M/L/C/Z and point counts) —
   * browsers interpolate matching parameters positionally, so mismatched
   * structures snap instead of morphing smoothly.
   */
  morphPaths?: string[];
  /** Custom path data, in objectBoundingBox (0..1) coordinates. Required when shape is "custom". */
  path?: string;
  shape?: SvgClipMaskShape;
}

export function SvgClipMask({
  children,
  shape = "blob",
  path,
  animate = "none",
  morphPaths,
  duration = DEFAULT_MORPH_DURATION,
  container,
  className,
}: SvgClipMaskProps) {
  const clipId = useId();
  const prefersReducedMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const shouldReduceMotion = prefersReducedMotion || !motionOn;
  const isHoverCapable = useHoverCapable();
  const [isHovered, setIsHovered] = useState(false);
  const [scrollIndex, setScrollIndex] = useState(0);

  const basePath =
    shape === "custom" ? (path ?? PRESET_PATHS.blob) : PRESET_PATHS[shape];
  const paths = morphPaths && morphPaths.length > 1 ? morphPaths : [basePath];

  const { scrollYProgress } = useScroll({
    container,
    offset: DEFAULT_SCROLL_OFFSET,
    target: hostRef,
  });

  useMotionValueEvent(scrollYProgress, "change", (value) => {
    if (shouldReduceMotion || animate !== "scroll" || paths.length < 2) {
      return;
    }
    const index = Math.min(paths.length - 1, Math.floor(value * paths.length));
    setScrollIndex(index);
  });

  const isMorphing =
    animate === "morph" && !shouldReduceMotion && paths.length > 1;

  const activeD = (() => {
    if (shouldReduceMotion || animate === "none" || isMorphing) {
      return paths[0];
    }
    if (animate === "scroll") {
      return paths[scrollIndex] ?? paths[0];
    }
    if (animate === "hover") {
      return isHoverCapable && isHovered ? (paths[1] ?? paths[0]) : paths[0];
    }
    return paths[0];
  })();

  return (
    <div
      className={cn("relative", className)}
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
      ref={hostRef} data-reduced={prefersReducedMotion ? "true" : "false"} data-slot="svg-clip-mask"
    >
      <svg aria-hidden="true" className="absolute h-0 w-0">
        <defs>
          <clipPath clipPathUnits="objectBoundingBox" id={clipId}>
            <motion.path
              animate={isMorphing ? { d: paths } : { d: activeD }}
              initial={false}
              transition={
                isMorphing
                  ? {
                      duration,
                      ease: EASE_MOVE,
                      repeat: Number.POSITIVE_INFINITY,
                      repeatType: "loop",
                    }
                  : { duration: TRANSITION_DURATION, ease: EASE_MOVE }
              }
            />
          </clipPath>
        </defs>
      </svg>
      <div
        className="h-full w-full"
        style={{
          clipPath: `url(#${clipId})`,
          WebkitClipPath: `url(#${clipId})`,
        }}
      >
        {children}
      </div>
    </div>
  );
}
